ged MCGetErrorMsg, MCGetDiscTitle, MCGetTrackTitle, MCGetName,;	 MCGetSpeeds to pass a pointer to the returned string buffer instead of;	 using TMLPascal's string function method.; D20 (DDH);	-Changed MCGetErrMsg to return the passed error message back as the;	 error indication if it doesn't have an error message specifically;	 for it (it then passes back the default error message.); D21 (DDH);	-MCStartUp returns error if already started up;	-MCShutdown return error if already shutdown;; D23 (DDH);	-Added MCSetVolume call;; D24 (DDH)	-Added IncBusyFlg stuff because were not reenterant (drivers do DecBusyFlg);;; D35 (DDH)	-Fixed McGetName to return MCToolkit NoPlayer if nothing connected.;;-----------------------------------------------------------------------------------------------	include 'MediaCtrlMgr.equ'	include 'all.macros'	include 'special.macros'	include 'e16.dialog'	title 'Media Control Toolset, Version 1.0';-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT MessLength320	IMPORT MessLength640	IMPORT Msg1_320	IMPORT Msg2_320	IMPORT Msg1_640	IMPORT Msg2_640	IMPORT WhatMessage320	IMPORT WhatMessage640	IMPORT alerttemp320	IMPORT alerttemp640	IMPORT UseCtrlPanelMsg_320	IMPORT UseCtrlPanelMsg_640	IMPORT EndUseCPMsg_320	IMPORT EndUseCPMsg_640	IMPORT EndMsg1_320	IMPORT EndMsg2_320	IMPORT EndMsg1_640	IMPORT EndMsg2_640	IMPORT OKButtonStr	IMPORT CancelButtonStr	IMPORT InsertDiskStr		;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY AppendString	ENTRY AppleTalkOn	ENTRY AppleTalkStr	ENTRY CloseID	ENTRY CloseParams	ENTRY CloseSetup	ENTRY CloseSetupID	ENTRY CloseSetupParams	ENTRY CopyString	ENTRY CreateSetupParams	ENTRY CurrentDriver	ENTRY CurrentNetName	ENTRY CurrentPort	ENTRY CurMediaDriver	ENTRY CurMediaDriver1	ENTRY CurMediaDriver2	ENTRY CurrentUser	ENTRY CurrentZoneName	ENTRY DefaultPort	ENTRY DefaultPrinter	ENTRY DefaultSetup	ENTRY DefaultZone	ENTRY DerefTemp1ToTemp2	ENTRY DestroyParams	ENTRY DirPath	ENTRY Dispatch	ENTRY DispatchAdr	ENTRY DisposePortList	ENTRY DisposePrinterList	ENTRY DriverError	ENTRY DriverPath	ENTRY DriverSubPath	ENTRY DummyDriver	ENTRY EndSetupFileInfo	ENTRY EntryAuxType	ENTRY EntryName	ENTRY EntryType	ENTRY EqualString	ENTRY Err0	ENTRY Err10	ENTRY Err12	ENTRY Err2	ENTRY Err4	ENTRY Err6	ENTRY Err8	ENTRY Exit0	ENTRY Exit2	ENTRY Exit4	ENTRY Exit6	ENTRY Exit8	ENTRY Exit10	ENTRY FreeFrame	ENTRY GetDirID	ENTRY GetDirParams	ENTRY GetEOFID	ENTRY GetEOFParams	ENTRY GetFileParams	ENTRY GetMem	ENTRY InitCursor	ENTRY InsertPortList	ENTRY InsertPrinterList	ENTRY Length	ENTRY ListSize	ENTRY LoadSomething	ENTRY MCCvtTime2Bin	ENTRY MCCvtBin2Time	ENTRY MCGetErrorMsg	ENTRY MCLoadDriver	ENTRY MCUnLoadDriver	ENTRY NoAppleTalk	ENTRY NumPorts	ENTRY NumPrinters	ENTRY OpenID	ENTRY OpenParams	ENTRY OpenSetup	ENTRY OpenSetupID	ENTRY OpenSetupParams	ENTRY MCActive	ENTRY MCBootInit	ENTRY MCReset	ENTRY MCShutDown	ENTRY MCStartup	ENTRY MCVersion	ENTRY PathBuffer	ENTRY PmGetPortName	ENTRY PmGetPrinterName	ENTRY PmInsertDisk	ENTRY PmSetPortName	ENTRY PmSetPrinterName	ENTRY PortInMem	ENTRY PortList	ENTRY PortListSize	ENTRY PostAlert	ENTRY PrChooser	ENTRY MediaDriverID	ENTRY DriverInMem	ENTRY PrinterList	ENTRY PrinterListSize	ENTRY ReadSetUpFile	ENTRY ReadSetupID	ENTRY ReadSetupParams	ENTRY SetCurrentDriver	ENTRY SetCurMediaDriver	ENTRY SetupDriverLists	ENTRY SetupFileInfo	ENTRY SetupFileName	ENTRY SetupFrame	ENTRY SizeOfFile	ENTRY TheEntry	ENTRY TransferCount	ENTRY UnLoadCurMediaDriver	ENTRY WaitCursor	ENTRY WriteSetupFile	ENTRY WriteSetupID	ENTRY WriteSetupParams	ENTRY insertdisk	ENTRY loadCurMediaDriver	ENTRY mcDummy;	Entry mcGetName	Entry mcDStartUp	Entry mcDShutDown	Entry mcGetFeatures	Entry mcPlay	Entry mcPause	Entry mcSendRawData	Entry mcGetStatus	Entry mcControl	Entry mcScan	Entry mcGetSpeeds	Entry mcSpeed	Entry mcStopAt	Entry mcJogN	Entry mcSearchTo	Entry mcSearchDone	Entry mcSearchWait	Entry mcGetPosition	Entry mcSetAudio	Entry mcGetTimes	Entry mcGetDiscTitle	Entry mcSetDiscTitle	Entry mcGetNoTracks	Entry mcGetTrackTitle	Entry mcSetTrackTitle	Entry mcGetProgram	Entry mcSetProgram	Entry mcGetDiscTOC	Entry mcGetDiscID	Entry mcRecord	Entry mcStop	Entry mcWaitRawData	Entry mcSetVolume;	ENTRY MChannel	ENTRY MChannel2	ENTRY MChannel4	ENTRY CP2Addr	ENTRY CDAddr	EXPORT CallTableCallTable	PROCTheStart		;	DC.L (TheEnd-TheStart)/4	DC.L MCBootInit-1	       	;1	DC.L MCStartup-1	       	;2	DC.L MCShutDown-1	       	;3	DC.L MCVersion-1	       	;4	DC.L MCReset-1	       	;5	DC.L MCActive-1	       	;6	DC.L mcDummy-1		;7 ***Dummy routine (Reserved)		DC.L mcDummy-1		;8 ***Dummy routine (Reserved)		DC.L mcGetErrorMsg-1     	;9 Gets error description		DC.L mcLoadDriver-1		;10 Loads a media ctrl driver		DC.L mcUnLoadDriver-1	;11 UnLoads a media ctrl driver		DC.L MCCvtTime2Bin-1	;12 Convert BCD time to Binary routine		DC.L MCCvtBin2Time-1	;13 Comvert Binary Time to BCD routine		DC.L mcGetTrackTitle-1	;14 Gets tracks title		DC.L mcSetTrackTitle-1	;15 Set tracks title		DC.L mcGetProgram-1		;16 Gets the programmed data		DC.L mcSetProgram-1		;17 Sets the program for the disc		DC.L mcGetDiscTitle-1	;18 Gets disc title	DC.L mcSetDiscTitle-1	;19 Sets disc title	DC.L mcDStartUp-1		;20 Driver Startup routine		DC.L mcDShutDown-1		;21 Driver Shutdown routine	DC.L mcGetFeatures-1	;22 Returns drivers features 		DC.L mcPlay-1		;23 Play command	DC.L mcPause-1		;24 Pause command	DC.L mcSendRawData-1	;25 Send raw data routine	DC.L mcGetStatus-1		;26 Get status routine		DC.L mcControl-1		;27 Sets device control info		DC.L mcScan-1		;28 Scan forward or reverse	DC.L mcGetSpeeds-1		;29 Get Speeds routine	DC.L mcSpeed-1		;30 Sets speed of device		DC.L mcStopAt-1		;31 Sets stopping point	DC.L mcJogN-1		;32 Jogs N no. of units		DC.L mcSearchTo-1		;33 Gets status of if done		DC.L mcSearchDone-1		;34 Waits for done	DC.L mcSearchWait-1		;35 Waits for search to finish		DC.L mcGetPosition-1	;36 Returns current positionn		DC.L mcSetAudio-1		;37 Controls Audio		DC.L mcGetTimes-1		;38 Gets disc times		DC.L mcGetDiscTOC-1		;39 Get disc table of contents		DC.L mcGetDiscID-1		;40 Get discs ID		DC.L mcGetNoTracks-1	;41 Gets disc's no. of tracks	DC.L mcRecord-1		;42 Turns the record mode on		DC.L mcStop-1		;43 Stops the device	DC.L mcWaitRawData-1	;44 Waits for raw data from the device	DC.L mcGetName-1		;45 Gets drivers name and version no.	DC.L mcSetVolume-1		;46 Sets the device's volume			;	DC.L PrChooser-1	      	;22*********??????;;;	DC.L PMInsertDisk-1	      39;	DC.L PMGetPrinterName-1   40;	DC.L PMGetPortName-1      41;	DC.L PMSetPrinterName-1   44;	DC.L PMSetPortName-1      45TheEnd			ENDP****************************************************************** SetUpFrame** Creates a stack direct page frame (saves direct page memory)** The Stack should look like this when we leave:*	DEFINESTACK* DPFrame	Block DirectStack* Bsave	Byte* Dsave	WORD******************************************************************	EXPORT SetUpFrameSetUpFrame	PROC;First inc. busy flag because were not reentereant	jsl IncBusyFlg	;inc. busy flag;Now save registers and setup environment	phb	; save dbr	phk	; set data bank to programs bank	plb		sta aregsave	;save a-reg. for restoring later		DEFINESTACKMyBReg	BYTEMyRTS	WORD	lda MyRTS,s	sta RTSSave	;save the rts so we can return	phd	;get current direct page	pla	;put into a-reg.	sta MyRTS,s	;put where RTS was on stack	;Now, reserve DirectStack bytes from stack for direct page	tsc							;get stack value	sec	sbc #DirectStack	;reserve bytes for d-page	tcs	inc a						;inc. by one for d-page start	tcd	;set direct page address	;Now, restore the RTS address on stack and restore the A-reg.	lda RTSsave	;get rts addres	pha	;put rts back on stack	lda aregsave	;restore the a-reg.	rts	aregsave	ds.w 1	;a-reg. save areaRTSSave	ds.w 1	;saved rts	ENDP****************************************************************** FreeFrame** Releases the created stack direct page******************************************************************	EXPORT FreeFrameFreeFrame	PROC;First, get the rts from the stack	ply	;get rts into y-reg.;Now restore the environment	tax	;save error in x-reg.;releases DirectStack bytes from stack	tsc							;get stack value	clc	adc #DirectStack	;release bytes	tcs	plb	pld	phy	;take y-reg. to restore the rts	rts	;return		ENDP****************************************************************** MCBootInit & MCReset** Does nothing.******************************************************************	EXPORT MCBootInitMCBootInit	PROC	EXPORT MCResetMCReset	EXPORT mcDummymcDummy	lda #0	clc	rtl	ENDP******************************************************************* MCStartup**       UserID	  word*       DirectPage	  word******************************************************************	EXPORT MCStartupMCStartup	PROC	DefineStackDPFrame	Block DirectStack	;direct page stack frameOrigB	BYTEOrigD	WORDRTL1	BLOCK 3RTL2	BLOCK 3UID	WORD		jsr SetupFrame	;setup direct page stack frame;First see if were already started	lda StartedFlag	;get flag	bne OKStartIt	;branch if not already started	lda #WasStarted	;return error, was already started	brl Exit2OKStartIt	stz StartedFlag	;clear flag indicating started up		lda UID,s	;Save passed userID	sta UserId;----------------------------------------------------------;; Setup Driver lists, read setup file and load; appropriate drivers.;;	pha;	_ListVersion	; check if list manager is loaded or not;		; if not start it up just in case;		; someone wants to select Choose Printer;	pla;	bcc AllIsWell;;	PushWord #28;	PushWord #0;	_LoadOneTool;;AllIsWell		;;Now check to see if we need to restart any drivers (MediaDriverID <>0)	ldx #14	stx StartUpCtrRestartLoop	ldx StartUpCtr	lda MediaDriverID,x	;get drivers ID	beq NoRestart	;branch if zero (nothing previously loaded)	pha	;space for results	pha	pha	pha	pha	pha	;pass userid of driver	_Restart	;attempt to restart driver	bcc RestartOK	;branch if no errors;We arrive here with an error attempting to restart a driver	ldx StartUpCtr	stz MediaDriverID,x	pla	;now just strip the results off	pla	pla	pla	pla	bra NoRestart	;go do next one;We arrive here with a successful restartRestartOK	pla	;get userid in a-reg	sta TempID	;save it for now	plx	;adr in x and y	ply	pla	;useless info	pla	;useless info	phy	;save addr back on stack	phx	ldx StartUpCtr	lda tempID	tay	;save copy in y for now	sta MediaDriverID,x	;set the new userID (probably same as old)	txa	asl a	;x times 2	tax	pla	sta DispatchAdr,x	;set dispatch addr low	pla	sta DispatchAdr+2,x	;set dispatch addr high	;Now do a driver startup		lda StartUpCtr	lsr a	;divide by two	inc a	;add one for 1-8	pha	;pass as media channel no.	lda CDaddr+2,x	;pass high word of ports long addr	pha	lda CDaddr,x	;pass low word of port name	pha	phy	;pass drivers UserID	ldx #$1426	jsl >$E10000	;perform MCDStartUp;	_MCDStartUp	;perform device startup	bcc NoRestart	;branch if no error trying to restart;We arrive here if the driver startup returned an error (unload the driver and purge)	lda StartUpCtr	sta MChannel2	asl a	sta MChannel4	lda #0	;we want unload and purge driver	jsr UnLoadCurMediaDriver ;unload the driver and flag as suchNoRestart	dec StartUpCtr	;dec. counter by two	dec StartUpCtr	bpl RestartLoop	;branch if not done with all channels		lda #0		sta NumPrinters	; number of printer	drivers found	sta NumPorts	; number of port drivers found	sta NoAppleTalk	; 1= AppleTalk driver found;	jsl SetupDriverLists ; find all the printer/port drivers in		; the DRIVERS folder and put them in a		; list for the list	manager to use;	bcs NoDriversFolder	; check if the Drivers folder was opened ok		; if not then just return w/o setting up default		; values or setting current printer etc,...;	jsl ReadSetUpFile	; get either the default settings for		; the choose printer dialog or read the		; printer.setup file for saved settings.;	jsr SetCurMediaDriver;	jsr SetCurrentDriver	;----------------------------------------------------------;; Set our WAP entry!;NoDriversFolder	pushword #$00	; system tool	Pushword #Toolnum	; this tool	pushword #0	; high word is zero	phd	; low word is d-reg	_SetWap;----------------------------------------------------------;; We're done:  clean up stack, and quit.;	lda #$0000	brl Exit2	EXPORT UserIDUserID	ds.w 1	;saved userIDTempID	ds.w 1	;temporary place to store returned IDStartUpCtr	ds.w 1	;counter used for startup	EXPORT StartedFlagStartedFlag	dc.w $ffff	;flag indicating started (0=started)	ENDP******************************************************************* MCShutDown** Shuts tool down.******************************************************************	EXPORT MCShutDownMCShutDown	PROC	jsr SetupFrame	;setup direct page stack frame;Now make sure it was started before trying to shutdown the tool	lda StartedFlag	;first make sure it was startedup	beq OKShutdown	;branch if was started	lda #WasShutdown	;else return not started error	brl Exit0	OKShutdown	lda #$ffff	sta StartedFlag;	jsr DisposePrinterList;	jsr DisposePortList;The following unloads any and all of the drivers	lda #14	;init. to last channel 0-7 (7*2)	sta MChannel2;This unloads the drivers but still saves the drivers ID for restartingUnloadLoop	lda MChannel2	;get channel no. times 2	tax	asl a	;times 2	sta MChannel4	;set times 4	lda #1	;we want unload and make restartable	jsr UnLoadCurMediaDriver ;unload the driver	dec MChannel2	;dec. by two the channel no.	dec MChannel2	bpl UnLoadLoop	;loop through all the channels;----------------------------------------------------------;; Clear the WAP;	pushword #$00	; system tool	Pushword #Toolnum	; this tool	PushLong #0	_SetWap	lda #$0000	brl Exit0		ENDP******************************************************************* MCActive** Returns whether or not the print manager is active.******************************************************************	EXPORT MCActiveMCActive	PROC	DefineStackRTL1	block 3RTL2	block 3ActiveResult	word;First inc. busy flag because were not reentereant	jsl IncBusyFlg	;inc. busy flag	cmp #0	bne AmActive	EXPORT FinishActiveFinishActive		;       	sta ActiveResult,s	jsl DecBusyFlg	;dec. busy flag	lda #0	clc	rtlAmActive	lda #True	bra FinishActive	ENDP******************************************************************* MCVersion** Returns version number******************************************************************	EXPORT MCVersionMCVersion	PROC;First inc. busy flag because were not reentereant	jsl IncBusyFlg	;inc. busy flag	lda #VersionNb	bra FinishActive	ENDP******************************************************************* PMInsertDisk** Routine that is used put up mount volume message.  This is an* entry point so that the drivers can use the code in the main* tool.******************************************************************	EXPORT PmInsertDiskPmInsertDisk	PROC	jsr SetupFrame	;setup direct page stack frame	jsr insertdisk	lda #0	brl exit0	ENDP******************************************************************* PMGetPrinterName* PMGetPortName** Returns a pointer	to the current name	on the stack******************************************************************	EXPORT PmGetPrinterNamePmGetPrinterName	PROC	jsr SetupFrame	;Setup direct page stack frame		jsr SetCurMediaDriver	lda #CurMediaDriver	ldx #^CurMediaDriver	bra SetPtr	EXPORT PMGetPortNamePMGetPortName		;       	jsr SetupFrame	;Setup direct page stack frame	jsr SetCurrentDriver	lda #CurrentDriver	ldx #^CurrentDriver	bra SetPtrSetPtr		;	DEFINESTACKDPFrame	Block DirectStack	;direct page stack frameOrigB	BYTEOrigD	WORDRTL1	block 3rtl2	block 3PtrResult	LONG	sta PtrResult,s	txa	sta PtrResult+2,s	lda #$0000	brl Exit0	ENDP******************************************************************* PMSetPrinterName* PMSetPortName**      PtrToNewName******************************************************************	EXPORT PmSetPrinterNamePmSetPrinterName	PROC	jsr SetCurMediaDriver	ldx #CurMediaDriver	; printer setting for appletalk	ldy #^CurMediaDriver	bra SetName	EXPORT PMSetPortNamePMSetPortName		;       	jsr SetCurrentDriver	ldx #CurrentPort	ldy #^CurrentPort	bra SetNameSetName		;	DEFINESTACKDPFrame	Block DirectStack	;direct page stack frameOrigB	BYTEOrigD	WORDRTL1	block 3rtl2	block 3NamePtr	LONG	jsr SetupFrame	;Setup direct page stack frame	jsl ReadSetupFile	; read the setup file	lda NamePtr,s	sta Temp1	lda NamePtr+2,s	sta Temp1+2	stx Temp2	sty Temp2+2	lda [Temp1]	and #$00FF	tay	dey	sep #%00100000	longa offNameLoop		;	lda [Temp1],y	sta [Temp2],y	dey	bpl NameLoop	rep #%00100000	longa on	jsl WriteSetupFile	; write it back out	lda #$0000	brl Exit4	ENDP****************************************************************************************************** MySetPrefix - This sets the prefix 8 correctly to support booting on a local volume* or over the network.** This routine save the old prefix 8 but doesn't restore it ( you need to restore when done.)*****************************************************************************************************MySetPrefix	Proc Export;First lets get the old prefix 8 and save it for restoring later.	_GetPrefixGS OldPfixParms	;get the old prefix 8 	bcs oops	_DInfoGS infoParms		;get the device name for the boot device	bcs oops	_VolumeGS volParms		;now do a Volume call to get the ID of the boot FST	bcs oops	lda fst_id		;get the ID number of the boot FST	cmp #$000D		;is it AppleShare?	bne local_boot		;no, must have been a local bootaShare_boot	_FSTSpecific fstParms	;do an FSTSpecific GetUserPath call	bcs oops		;punt if we can't determine the pathname of the user's folder	ldx userPfx		;get the pointer to the prefix	ldy userPfx+2	bra do_setPfx		;go set the prefixlocal_boot	ldx #localPfx		;get the pointer to the local prefix	ldy #localPfx>>16do_setPfx	stx prefix		;store the pointer to the prefix to use	sty prefix+2	_SetPrefixGS pfxParms	;set the prefix to the correct locationoops	rts				;return to caller, carry set if an error occurredinfoParms	dc.w 2		;pCount	dc.w 1		;device number (boot device is ALWAYS device 1)	dc.l devName		;pointer to result buffer for device namedevName	dc.w 36		;buffer lengthdevName2	dc.w 0		;string length	ds.b 32		;buffer for device namevolParms	dc.w 5		;pCount	dc.l devName2		;pointer to device name	dc.l volname		;pointer to volume name buffer	dc.l 0		;total blocks	dc.l 0		;free blocksfst_id	dc.w 0		;FST ID numbervolname	dc.w 36		;buffer lengthvolname2	dc.w 0		;string length	ds.b 32		;string bufferfstParms	dc.w 3		;pCount	dc.w $000d		;FST ID number (AppleShare)	dc.w 8		;command number (GetUserPath)userPfx	ds.l 1		;space for the prefix pointerpfxParms	dc.w 2		;pCount	dc.w 8		;prefix numberprefix	ds.l 1		;space for the prefix pointerlocalPfx	dc.w 31	dc.b '*/System/Drivers/Media.Control/'OldPfixParms	dc.w 2		;pCount	dc.w 8		;prefix number (8)	dc.l OldPrefixS		;ptr to prefix output string areaOldPrefixS	dc.w 84		;buffer length	EXPORT OldPrefixOldPrefix	dc.w 0		;length of prefix	ds.b 80		;prefix buffer	EXPORT RestorePFixRestorePFix	dc.w 2		;pcount	dc.w 8		;prefix number (8)	dc.l OldPrefix		;saved prefix buffer	ENDP******************************************************************* MCLoadDriver** The result is also a word value which	tells the caller whether the call was* successful or not.** If result was False then error was invalid parameter passed, else it is just* the result of loader call _InitialLoad******************************************************************	EXPORT MCLoadDriverMCLoadDriver	PROC	DEFINESTACKDPFrame	Block DirectStack	;direct page stack frameOrigB	BYTEOrigD	WORDRTL1	block 3RTL2	block 3SMCChannel	WORD	;Media Control Channel No.	jsr SetupFrame	;Setup direct page stack frame	lda SMCChannel,s	;get media channel no.	dec a	;dec. so will be zero base	sta MChannel	;save it	asl a	;times 2	sta MChannel2	;save times 2	asl a	sta MChannel4	;save times 4		lda MChannel2	tax	lda MediaDriverID,x ;non-zero indicates that driver is loaded	beq OK2load	; check if anything is loaded;We arrive here if there currently is a loaded driver for this particular media channel	lda #0	;we want to unload and purge driver and id	jsr UnloadCurMediaDriverOK2load	jsr LoadCurMediaDriver ;Now load the driver	bra ErrorExit			lda #0	;ErrorExit		brl Exit2	ENDP******************************************************************* MCUnloadDriver** The result is also a word value which	tells the caller whether the call was* successful or not.** If result was False then error was invalid parameter passed, else it is just* the result of loader call _UserShutDown******************************************************************	EXPORT MCUnloadDriverMCUnloadDriver	PROC	DefineStackDPFrame	Block DirectStack	;direct page stack frameOrigB	BYTEOrigD	WORDRTL1	block 3RTL2	block 3SMCChannel	WORD	;Media Control Channel No.	jsr SetupFrame	;setup direct page stack frame	lda SMCChannel,s	;get media channel no.	dec a	;dec. so will be zero base	sta >MChannel	;save it	asl a	;times 2	sta >MChannel2	;save times 2	asl a	sta >MChannel4	;save times 4		lda >MChannel2	tax	lda >MediaDriverID,x ;non-zero indicates that driver is loaded	beq ErrorOut	; branch if nothing to unload	lda #0	;we want unload and purge driver		jsr UnloadCurMediaDriver	brl Exit2ErrorOut	lda #NotLoaded	;return with not loaded error	brl Exit2	ENDP****************************************************************** PrChooser**     ResultCode** Returns True if user picks*****************************************************************	EXPORT PrChooserPrChooser	PROC	definestackDPFrame	Block DirectStack	;direct page stack frameOrigB	byteOrigD	wordRTL1	block 3RTL2	block 3Result	word	jsr SetupFrame	;setup direct page stack frame		lda #True	sta result,s	; return true since OK hit, some apps depend on		; this being true		pha	; make room for result	_GetMasterSCB	pla	pha	; make room for result of alert call	and #$80	; check mode	beq mode320	; 320 mode	lda #UseCtrlPanelMsg_640		sta WhatMessage640	lda #^UseCtrlPanelMsg_640		sta WhatMessage640+2	lda #EndUseCPMsg_640-UseCtrlPanelMsg_640	sta MessLength640	pushlong #alerttemp640 ; use 640 mode template	bra GoOn	mode320		lda #UseCtrlPanelMsg_320		sta WhatMessage320	lda #^UseCtrlPanelMsg_320		sta WhatMessage320+2	lda #EndUseCPMsg_320-UseCtrlPanelMsg_320	sta MessLength320	pushlong #alerttemp320 ; use 320 mode templateGoOn	pushlong #$0000	_NoteAlert	pla	; get the item hit off stack	lda #0	brl Exit0	ENDP;-------------------------------------------------------------------;;  NAME:	UniqueFile;;  PURPOSE:	To create the unique file name for the resource data base;;  PASSED:	(A-reg.)=	WORD (low word of unique number.);	(X-reg.)=	WORD (high word of unique number.);							non-zero (do create res. file if not already there);-------------------------------------------------------------------UniqueFile    	PROC;First save the unique no.	sta Unique	stx Unique+2;Now create the unique file name using the passed unique ID number.;First lets set the prefix of the file name (the CD. or LD. or VD.)	txa	and #$f000	clc	rol a	rol a	rol a	rol a	rol a	rol a	tax	lda PrefixTbl,x	;get prefix from table	sta MCFileName	;stuff into file name;Now convert the rest of the unique number into ascii digits	sep #$30	;go into 8-bit mode	longa off	longi off	ldy #9	;init. index into string	ldx #0	;init index into long word uniqueMoreLoop	lda Unique,x	;first do low nibble	jsr MyMakeASCII	;make the low byte ascii	sta MCFileName,y	;stuff into file name	dey	cpy #3	bcc AllDone	lda Unique,x	;now do high nibble	lsr a	lsr a	lsr a	lsr a	jsr MyMakeASCII	sta MCFileName,y	inx	dey	bra MoreLoop	AllDone		rep #$30	;back into 16-bit mode	longa on	longi on	rts;------------------------------------------------------------------------------;Assumes in 8-bit mode	longa off	longi offMyMakeASCII	and #$0f	cmp #$0a	bcc OK1	;branch if 0-9 digit	clc	adc #7	;add 7 to make offset from char. AOK1	clc	adc #'0'	;add offset from char. zero	rts	longa on	longi on;-----------------------------------------------------------------------------	PrefixTbl	dc.b 'CD'	;$0HMMSSFF	dc.b 'LD'	;$1HMMSSFF	dc.b 'VD'	;$2HMMSSFF	dc.b 'M3'	;$3HMMSSFF	dc.b 'M4'	;$4HMMSSFF	dc.b 'M5'	;$5HMMSSFF	dc.b 'M6'	;$6HMMSSFF	dc.b 'M7'	;$7HMMSSFF	dc.b 'M8'	;$8HMMSSFF	dc.b 'M9'	;$9HMMSSFF	dc.b 'A1'	;$AHMMSSFF	dc.b 'A2'	;$BHMMSSFF	dc.b 'A3'	;$CHMMSSFF	dc.b 'A4'	;$DHMMSSFF	dc.b 'A5'	;$EHMMSSFF	dc.b 'A6'	;$FHMMSSFF			EXPORT MyResPathUnique	ds.l 1	;temporary space for unique no.MyResPath	dc.w 12	dc.b '8/'MCFileName	dc.b 'XX.HMMSSFF'	;This is the create file name	ENDP;-------------------------------------------------------------------;;  NAME:	RStartUp;;  PURPOSE:	To start things up for using resources;;  PASSED:	(A-reg.)=	zero (dont create resource file if not already there);							non-zero (do create res. file if not already there);-------------------------------------------------------------------RStartUp    PROC	sta MyCreateRFlag	;store passed create flag	stz MyResFileID	;init. res file id as unopened;First lets make sure the resource manager is opened	pushword #0	;space for result	_ResourceStatus	;get status of resource mgr.	bcc NoErr	;branch if no error	plx	;just get off stack	rts	;exit with errorNoErr	pla	;get result	bne RGoOn	;branch if active;We arrive here with the resource manager tool not active	lda #NoResMgr	;return with no resource manager error	sec	rts;At this point the resource manager is there so we can proceedRGoOn	ldx #$4026	;use this tools userID	stx DUserID	;save new userID;Now get the current resource applicaitions userid and save it;for restoring when we leave.	pha	;space for result	_GetCurResourceApp	;get current resources userid	pla	sta OldResApp	;save old resources userid;Now get this drivers userid and register with the resource manager	Pushword DUserID	_ResourceStartUp	;register with the resource manager	sta AnyError	;**************;Now get the old level and save it and then set it to zero;(This helps the protect the resource fork from being closed accidentally.)	_GetLevelGS GetLevelBlk	sta AnyError	;**************	lda TheLevel	sta OldLevel	;save the old level	stz TheLevel	;set the level to zero	_SetLevelGS GetLevelBlk ;set the level	sta AnyError	;**************;Now get the system preferences and save them	_GetSysPrefsGS GetPrefsBlk	sta AnyError	;**************	lda ThePrefs	sta OldPrefs	;save the old prefs;Now set the system preferences so that when we do an openresouce call,;the user will be prompted to insert the disk containing the file if the;volume is currently not online.	and #$1fff	;and out unwanted bits	ora #$8000	;or on the insert dialog wanted bit	sta ThePrefs	_SetSysPrefsGS GetPrefsBlk ;set the new system preferences	sta AnyError	;**************;Now set the prefix 8 (for networked booting to look in users directory.)	jsr MySetPrefix	;go set prefix 8;-----------------;Now we can finally try and open the resource file	pha	;space for result	pushword #$0003	;access word (Read/write)	pushlong #0	;resource map area Nil	pushlong #MyResPath	;pointer to pathname	_OpenResourceFile	plx	;get resourcefile ID		bcs SeeCreate	;branch if got an error (see if need to create)	stx MyResFileID	;save the opened resource file ID	lda #0	;indicate no errorsGotErrjmp	jmp GotError1	;continue with no error reported;We arrive here when an error occured while trying to open the resource file.SeeCreate;Now lets see if it was an $0046 GS/OS file error: File Not Found;                       or $0044 GS/OS file error: Path Not Found	cmp #$0044	;is it a Path not found error?	beq SeeCreate2	;yes, go see if want to create resource	cmp #$0046	;is it a File not found error?	bne GotErrjmp	;branch if not;We arrive here if we have a file or path not found error and we need to see if need to create it.SeeCreate2	ldx MyCreateRFlag	;get create resource flag	beq GotErrjmp	;branch if dont want to create a new res. file;Ok, now lets create that new resource file	pushlong #$00000101	;aux. file type	pushword #$005c	;file type (multimedia document)	pushword #$00c3	;file access	pushlong #MyResPath	;pathname	_CreateResourceFile	;create the resource file	bcs GotErrjmp	;branch if error;We now should be able to open this newly created resource	pha	;space for result	pushword #$0003	;access word (Read/write)	pushlong #0	;resource map area Nil	pushlong #MyResPath	;pointer to pathname	_OpenResourceFile	plx	;get resourcefile ID	bcs GotErrJmp	;branch if got an error (somethings weird)	stx MyResFileID	;save the opened resource file ID;Now lets create the Signature resource				pha	;space for resultant handle	pha	pushword #0	;high word of length (zero)	lda MySigR	;get length of string	and #$00ff	inc a	sta MyStrLength	;save length	pha	;pass low word of length	pushword DUserID	;drivers userid	pushword #$0018	;attributes (dont purge, no cross bank, no special)	pushLong #0	;nil pointer	_newhandle	plx	stx MyNewHandle	plx	stx MyNewHandle+2	bcc OK1	;branch if no errorFinishUpJ	jmp GotError1	;error;Now copy over the string into the handle data areaOK1	PushLong #MySigR	;source (signature string)	PushLong MyNewHandle ;Push destination of handle	PushLong MyStrLength ;Push strings length	_PtrToHand	;Now copy the string into handle	bcs FinishUpJ	;branch if any errors;OK, now we have the data in the handle so we can creat a resource with it	PushLong MyNewHandle ;handle of data for resource	PushWord #$0000	;attributes of resource	pushword #$8006	;resource type (rPString)	pushlong #1	;resource ID (1 for signature resource)	_AddResource			;Now restore a few things and finish upGotError1	pha	;save error value;Now restore SysPrefs	lda OldPrefs	sta ThePrefs	;restore the prefs value	_SetSysPrefsGS GetPrefsBlk	sta AnyError	;**************;Now restore the level	lda OldLevel	sta TheLevel	_SetLevelGS GetLevelBlk;restore the level	sta AnyError	;**************	pla	;get error value	pha	beq WasOK	;branch if nonerror exit;Now shutdown the resource manager	_ResourceShutdown	;unregister this driver userid with res magr.	sta AnyError	;**************;Now restore the ResourceApp userid	pushword OldResApp	_SetCurResourceApp	sta AnyError	;**************	;Now restore the prefix 8		_SetPrefixGS RestorePFix ;restore the prefix-8	WasOK	pla	cmp #1	;this sets the carry if there was an error									rtsMyCreateRFlag 	ds.w 1	;flag to indicate to create resource (0=not to		;create, not zero=to create resource)	EXPORT MyResFileIDMyResFileID	ds.w 1	;my resource file id (non zero if opened)	EXPORT OldResAppOldResApp	ds.w 1	;space to save old resource app useridOldLevel	ds.w 1	;old level no. valueOldPrefs	ds.w 1	;old system preferences valueMySigR	str 'v1.0, Media Control'MyNewHandle 	ds.l 1	;new handle storage areaMyStrLength	dc.l 0	;signatures string length (want long for zeros)				EXPORT AnyErrorAnyError	dc.w 0	;********************;=====================================================================GetLevelBlk	dc.w 1	;pcount=1TheLevel	ds.w 1	;level no.;=====================================================================GetPrefsBlk	dc.w 1	;pcount=1ThePrefs	ds.w 1	;preferences	EXPORT DUserIDDUserID	ds.w 1	;driver userid (tool038 users ID)	ENDP;-------------------------------------------------------------------;;  NAME:	RShutDown;;  PURPOSE:	To shut things down after using resources;;-------------------------------------------------------------------RShutDown   PROC;Now shutdown the resource manager	_ResourceShutdown	;unregister this driver userid with res magr.;Now restore the ResourceApp userid	pushword OldResApp	_SetCurResourceApp;Now restore the prefix 8		_SetPrefixGS RestorePFix ;restore the prefix-8				rts	ENDP;-------------------------------------------------------------------;;  NAME:	MCGetDiscTitle;;  PURPOSE:	To return the discs title;;  PASSED:	UniqueID	LONG	;unique media ID number;	DiscTitle	LONG	;string ptr to where title will go;	;  RETURNED:	NONE;;-------------------------------------------------------------------MCGetDiscTitle 	PROC	DefineStackZPBlock	block	DirectStackOrigB	byteOrigD	wordRTL1	block 3RTL2	block 3DiscTitle	long	;passed string pointer for returned disc titleUniqueID	long				jsr SetupFrame	;setup direct page stack frame	;First create the unique file name using the passed unique ID.	lda UniqueID+2,s	;pass high word in x-reg. of unique ID	tax	lda UniqueID,s	;pass low word of unique id	jsr UniqueFile	;create unique file ID			lda #0	;indicate not to create res. file if not there	jsr RStartUp	;start things up for getting the resource	bcs OutOfHere	;branch if error on startup;Now that we have the resource file, we can do the real work	pha	pha	;space for long result	pushword #$8006	;resource type	pushlong #2	;resource ID	_LoadResource	plx	;save low word of handle	ply	;save high word of handle	bcs FinishErr	;branch if error;Now get the handle size and send the data back	sty MyResHandle+2	stx MyResHandle	lda DiscTitle,s	;get disc title and save it	sta MyDiscTitle	lda DiscTitle+2,s	sta MyDiscTitle+2	PushLong MyResHandle ;for _HandToPtr call	PushLong MyDiscTitle ;for _HandToPtr call	pha						;space for long result	pha						;space for long result	PushLong MyResHandle ;This is for _GetHandleSize call	_GetHandleSize	;Now size of handle is on stack	_HandToPtr	;Now copy the string back			;Now just finish things upFinishUp	jsr RShutDown 	;shut down the resource stuff	bcs OutOfHere	lda #0	;return no errors			OutOfHere	jmp Exit8;We arrive here with an error, we must attempt to shut down things;before returningFinishErr	cmp #$1e06	;see if resource not found error	bne WhoKnows	;branch if unknown	lda #ItemNotThere	;return with item not found errorWhoKnows	pha	;save error value;now copy back over a null string	pushlong #MyNullStr	;source	pushlong MyDiscTitle ;destination	pushlong #2	;no. of bytes	_blockmove	;move a null string back	jsr RShutDown	;shut her down	pla	;restore the error value	bra OutOfHere				EXPORT MyResHandleMyResHandle	dc.l 0	EXPORT MyNullStrMyNullStr	dc.w 0MyDiscTitle	dc.l 0	ENDP;-------------------------------------------------------------------;;  NAME:	MCSetDiscTitle;;  PURPOSE:	To set the discs title;;  PASSED:	UniqueID	LONG	;unique media ID no.;	DiscTitlePtr	LONG	;pointer to new discs title str.;;  RETURNED:	None;;-------------------------------------------------------------------MCSetDiscTitle 	PROC	DefineStackZPBlock	block	DirectStackOrigB	byteOrigD	wordRTL1	block 3RTL2	block 3DiscTitlePtr 	LONGUniqueID	LONG		jsr SetupFrame	;setup direct page stack frame;First create the unique file name using the passed unique ID.	lda UniqueID+2,s	;pass high word in x-reg. of unique ID	tax	lda UniqueID,s	;pass low word of unique id	jsr UniqueFile	;create unique file ID		lda #$ffff	;indicate to create res. file if not there	jsr RStartUp	;start things up for getting the resource	bcc AOK1	;branch if no errors starting up	jmp OutOfHere;Now that we have the resource file, we can do the real work;First we need to create a handle for the passed P-string.;But first, we need to determine the size of the string that we haveAOK1	lda DiscTitlePtr,s	sta DP0	sta MyDiscTitle	lda DiscTitlePtr+2,s	sta MyDiscTitle+2	sta DP2	lda [DP0]	;got the strings length	and #$00ff	inc a	;add one for the p-string zero length	sta MyStrLength	;save the strings length				pha	;space for resultant handle	pha	pushword #0	;high word of length (zero)	pushword MyStrLength ;low word of length	pushword DUserID	;drivers userid	pushword #$0018	;attributes (dont purge, no cross bank, no special)	pushLong #0	;nil pointer	_newhandle	plx	stx MyNewHandle	plx	stx MyNewHandle+2	bcc OK1	;branch if no errorFinishUpJ	jmp FinishUp	;error;Now copy over the data into the handle data area;But first we need to add 2 to the strings pointer to point to the string dataOK1	Pushlong MydiscTitle 	;Push title pointer	PushLong MyNewHandle	;Push destination of handle	PushLong MyStrLength	;Push strings length	_PtrToHand		;Now copy the string into handle	bcs FinishUpJ		;branch if any error			;Now we need to remove any old program that might exist	PushWord #$8006	;rPString	PushLong #2	;resource ID=2	_RemoveResource	;this removes any existing resource;Note: we dont care if we get an error, we just want to make sure the resorce;has been removed so we can add the new one to it.;OK, now we have the data in the handle so we can creat a resource with it	PushLong MyNewHandle ;handle of data for resource	PushWord #$0000	;attributes of resource	pushword #$8006	;resource type	pushlong #2	;resource ID	_AddResource			;Now just finish things upFinishUp	pha	;save error no	jsr RShutDown	;shut down the resource stuff	bcc NoSDErr	;branch if no shut down error	plx	cpx #0	beq OutOfHere	;branch if no error before shutdown (return shutdown error)	txa	;get old error number	bra OutOfHere	;else return error before shutdown errorNoSDErr	plaOutOfHere	jmp Exit8			MyDiscTitle	dc.l 0	;pointer to passed stringMyStrLength	dc.l 0	;length of data string (want long, zeros for high word)MyNewHandle	dc.l 0	;created handle	ENDP;-------------------------------------------------------------------;;  NAME:	MCGetTrackTitle;;  PURPOSE:	To return a tracks title;;  PASSED:	UniqueID	LONG	;unique media ID number;	TrackNo	WORD	;track number;	TrackTitle	LONG	;string pointer for returned Tracks title;  RETURNED:	NONE;;-------------------------------------------------------------------MCGetTrackTitle PROC	DefineStackZPBlock	block DirectStackOrigB	byteOrigD	wordRTL1	block 3RTL2	block 3TrackTitle	long	;passed string pointer to returned bufferTrackNo	wordUniqueID	long				jsr SetupFrame	;setup direct page stack frame;First create the unique file name using the passed unique ID.	lda UniqueID+2,s	;pass high word in x-reg. of unique ID	tax	lda UniqueID,s	;pass low word of unique id	jsr UniqueFile	;create unique file ID		lda TrackNo,s	clc	adc #100	;add 100 for resouce ID	sta MyTrackNo	;save the track no.				lda #0	;indicate not to create res. file if not there	jsr RStartUp	;start things up for getting the resource	bcs OutOfHere	;branch if error on startup;Now that we have the resource file, we can do the real work	pha	pha	;space for long result	pushword #$8006	;resource type	pushword #0	;high word of resource ID	pushword MyTrackNo	;low word of resource ID	_LoadResource	plx	;save low word of handle	ply	;save high word of handle	bcs FinishErr	;branch if error;Now get the handle size and send the data back	sty MyResHandle+2	stx MyResHandle	lda TrackTitle,s	;get tracks title and save it	sta MyTrackTitle	lda TrackTitle+2,s	sta MyTrackTitle+2	PushLong MyResHandle ;for _HandToPtr call	PushLong MyTrackTitle ;for _HandToPtr call	pha						;space for long result	pha						;space for long result	PushLong MyResHandle ;This is for _GetHandleSize call	_GetHandleSize	;Now size of handle is on stack	_HandToPtr	;Now copy the string back			;Now just finish things upFinishUp	jsr RShutDown	;shut down the resource stuff	bcs OutOfHere	lda #0	;return no errors			OutOfHere	jmp Exit10;We arrive here with an error, we must attempt to shut down things;before returningFinishErr	cmp #$1e06	;see if resource not found error	bne WhoKnows	;branch if unknown	lda #ItemNotThere	;return with item not found errorWhoKnows	pha	;save error value;now copy back over a null string	pushlong #MyNullStr	;source	pushlong MyTrackTitle ;destination	pushlong #2	;no. of bytes	_blockmove	;move a null string back	jsr RShutDown	;shut her down	pla	;restore the error value	bra OutOfHere			MyTrackTitle	dc.l 0MyTrackNo	ds.w 1	ENDP;-------------------------------------------------------------------;;  NAME:	MCSetTrackTitle;;  PURPOSE:	To set a tracks title;;  PASSED:	UniqueID	LONG	;unique media ID number;	TrackNo	WORD	;track number;	DiscTitlePtr	LONG	;pointer to new discs title str.;;  RETURNED:	None;;-------------------------------------------------------------------MCSetTrackTitle 	PROC	DefineStackZPBlock	block DirectStackOrigB	byteOrigD	wordRTL1	block 3RTL2	block 3DiscTitlePtr 	LONGTrackNo	wordUniqueID	long	jsr SetupFrame	;setup direct page stack frame;First create the unique file name using the passed unique ID.	lda UniqueID+2,s	;pass high word in x-reg. of unique ID	tax	lda UniqueID,s	;pass low word of unique id	jsr UniqueFile	;create unique file ID		lda TrackNo,s	;get track no.	clc	adc #100	;add 100 for resource id	sta MyTrackNo	;save for later				lda #$ffff	;indicate to create res. file if not there	jsr RStartUp	;start things up for getting the resource	bcc AOK1	;branch if no errors starting up	jmp OutOfHere;Now that we have the resource file, we can do the real work;First we need to create a handle for the passed P-string.;But first, we need to determine the size of the string that we haveAOK1	lda DiscTitlePtr,s	sta DP0	sta MyDiscTitle	lda DiscTitlePtr+2,s	sta MyDiscTitle+2	sta DP2	lda [DP0]	;got the strings length	and #$00ff	inc a	;add one for the p-string zero length	sta MyStrLength	;save the strings length				pha	;space for resultant handle	pha	pushword #0	;high word of length (zero)	pushword MyStrLength ;low word of length	pushword DUserID	;drivers userid	pushword #$0018	;attributes (dont purge, no cross bank, no special)	pushLong #0	;nil pointer	_newhandle	plx	stx MyNewHandle	plx	stx MyNewHandle+2	bcc OK1	;branch if no errorFinishUpJ	jmp FinishUp	;error;Now copy over the data into the handle data area;But first we need to add 2 to the strings pointer to point to the string dataOK1	Pushlong MydiscTitle	;Push title pointer	PushLong MyNewHandle	;Push destination of handle	PushLong MyStrLength	;Push strings length	_PtrToHand	;Now copy the string into handle	bcs FinishUpJ	;branch if any error			;Now we need to remove any old program that might exist	PushWord #$8006	;rPString	PushLong MyTrackNo	;resource ID (created form passed track no.)	_RemoveResource	;this removes any existing resource;Note: we dont care if we get an error, we just want to make sure the resorce;has been removed so we can add the new one to it.;OK, now we have the data in the handle so we can creat a resource with it	PushLong MyNewHandle ;handle of data for resource	PushWord #$0000	;attributes of resource	pushword #$8006	;resource type	pushlong MyTrackNo	;resource ID (passed track no.+100)	_AddResource			;Now just finish things upFinishUp	pha	;save error no	jsr RShutDown	;shut down the resource stuff	bcc NoSDErr	;branch if no shut down error	plx	cpx #0	beq OutOfHere	;branch if no error before shutdown (return shutdown error)	txa	;get old error number	bra OutOfHere	;else return error before shutdown errorNoSDErr	plaOutOfHere	jmp Exit10			MyDiscTitle	dc.l 0	;pointer to passed stringMyStrLength	dc.l 0	;length of data string (want long, zeros for high word)MyNewHandle	dc.l 0	;created handleMyTrackNo	dc.l 0	;created resource id from track no. (long for high word zeros)	ENDP;-------------------------------------------------------------------;;  NAME:	MCGetProgram;;  PURPOSE:	To get a discs program information;;  PASSED:	UniqueID	LONG	;unique media ID number;	DiscProgram	Pointer	;Pointer to GSOS return string of Discs program info.;;  RETURNED:	None;;-------------------------------------------------------------------MCGetProgram PROC	DefineStackZPBlock	block DirectStackOrigB	byteOrigD	wordRTL1	block 3RTL2	block 3DiscProgram	long	;passed pointer to GSOS result string pointerUniqueID	long				jsr SetupFrame	;setup direct page stack frame;First create the unique file name using the passed unique ID.	lda UniqueID+2,s	;pass high word in x-reg. of unique ID	tax	lda UniqueID,s	;pass low word of unique id	jsr UniqueFile	;create unique file ID		stz MyExitStr	;init. for null returned string	lda DiscProgram,s	;get disc title and save it	sta DP0	clc	adc #2	sta MyDiscProgram	;save buffers return word address (+2)	lda DiscProgram+2,s	sta DP2	adc #0	sta MyDiscProgram+2;Now get the buffers length	lda [DP0]	;get the buffers length word	sec	sbc #4	;subtract out 4 bytes for buffer length and string length	sta BufferLen;Now do some real work				lda #0	;indicate not to create res. file if not there	jsr RStartUp	;start things up for getting the resource	bcc GoOn2	jmp OutOfHere	;branch if error on startup;Now that we have the resource file, we can do the real workGoOn2	pha	pha	;space for long result	pushword #$801d	;resource type (rCString)	pushlong #1	;resource ID (for program)	_LoadResource	plx	;save low word of handle	ply	;save high word of handle	bcc GoOn1	jmp FinishErr	;jmp if error;Now save the handle GoOn1	sty MyResHandle+2	stx MyResHandle	;save the handle;Now get the handles data size				pha						;space for long result	pha						;space for long result	PushLong MyResHandle ;This is for _GetHandleSize call	_GetHandleSize	;Now size of handle is on stack	pla	dec a	;subtract out one for zero terminator we dont want	sta ActualLen	;save actual length of string	plx						;dont care abount high word	cmp BufferLen	;compare with the buffers length	beq OKLen	;branch if ok	bcc OKLen;We arrive here with a buffer size too small;So we set the length word to the size needed and return with;a buffer to small error	sta MyExitStr	;set for returned exit string	lda #$004f	;return with GS/OS buffer to small error	bra FinishErr;We arrive here with a buffer size larger enough to copy it overOKLen;First copy over the string size	pushlong #ActualLen	;source	pushlong MyDiscProgram ;destination	pushlong #2	;no. of bytes	_blockmove	;move the strings length over	lda MyDiscProgram	;bump pointer 2 bytes to string area of GS/OS string	clc	adc #2	sta MyDiscProgram	lda MyDiscProgram+2	adc #0	sta MyDiscProgram+2	PushLong MyResHandle ;for _HandToPtr call	PushLong MyDiscProgram ;for _HandToPtr call	PushWord #0	;high word zero of length	PushWord ActualLen	;low word is actual length	_HandToPtr	;Now copy the string back			;Now just finish things upFinishUp	jsr RShutDown	;shut down the resource stuff	bcs OutOfHere	lda #0	;return no errors			OutOfHere	jmp Exit8;We arrive here with an error, we must attempt to shut down things;before returningFinishErr	cmp #$1e06	;see if resource not found error	bne WhoKnows	;branch if unknown	lda #ItemNotThere	;return with item not found errorWhoKnows	pha	;save error value;now copy back over a null string;Now we will copy string length of zero back	pushlong #MyExitStr	;source	pushlong MyDiscProgram	;destination	pushlong #2	;no. of bytes	_blockmove	;move a null string back	jsr RShutDown	;shut her down	pla	;restore the error value	bra OutOfHere			ActualLen	dc.w 0	;actual length of the returned resource stirngBufferLen 	dc.w 0	;length of the GS/OS buffer providedMyDiscProgram 	dc.l 0MyDiscString 	dc.l 0MYExitStr 	dc.w 0	;this is stuffed with the returned error word length	ENDP;-------------------------------------------------------------------;;  NAME:	MCSetProgram;;  PURPOSE:	To set a disc's program information;;  PASSED:	UniqueID	LONG	;unique media ID number;	DiscProgPtr	LONG	;pointer to new discs prog. str.;;  RETURNED:	None;;-------------------------------------------------------------------MCSetProgram 	PROC	DefineStackZPBlock	block DirectStackOrigB	byteOrigD	wordRTL1	block 3RTL2	block 3DiscProgPtr 	LONGUniqueID	LONG	jsr SetupFrame	;setup direct page stack frame;First create the unique file name using the passed unique ID.	lda UniqueID+2,s	;pass high word in x-reg. of unique ID	tax	lda UniqueID,s	;pass low word of unique id	jsr UniqueFile	;create unique file ID		lda #$ffff	;indicate to create res. file if not there	jsr RStartUp	;start things up for getting the resource	bcc AOK1	;branch if no errors starting up	jmp OutOfHere;Now that we have the resource file, we can do the real work;First we need to create a handle for the passed GS/OS string.;But first, we need to determine the size of the string that we haveAOK1	lda DiscProgPtr,s	sta DP0	sta MyDiscTitle	lda DiscProgPtr+2,s	sta MyDiscTitle+2	sta DP2	lda [DP0]	;got the strings length	inc a	;add one for the cstring zero terminator	sta MyStrLength	;save the strings length				pha	;space for resultant handle	pha	pushword #0	;high word of length (zero)	pushword MyStrLength ;low word of length	pushword DUserID	;drivers userid	pushword #$0018	;attributes (dont purge, no cross bank, no special)	pushLong #0	;nil pointer	_newhandle	plx	stx MyNewHandle	plx	stx MyNewHandle+2	bcc OK1	;branch if no errorFinishUpJ	jmp FinishUp	;error;Now copy over the data into the handle data area;But first we need to add 2 to the strings pointer to point to the string dataOK1	lda MyDiscTitle	clc	adc #2	sta MyDiscTitle	lda MyDiscTitle+2	adc #0	sta MyDiscTitle+2	pha						;push high word	Pushword MydiscTitle ;Push low word	PushLong MyNewHandle ;Push destination of handle	PushLong MyStrLength ;Push strings length (+1 for zero term.)	_PtrToHand	;Now copy the string into handle	bcs FinishUpJ	;branch if any error;Now we need to add the zero terminator byte to the end of the cstring	PushLong MyNewHandle	_HLock	;first lock the handle down	bcs FinishUpJ	;branch if any error;Now derefernce the handle	lda MyNewHandle	sta DP0	lda MyNewhandle+2	sta DP2	lda [DP0]	;now get the pointer to the data string	sta DP4	ldy #2	lda [DP0],y	 sta DP6	ldy MyStrLength	;get index to end of string	dey;now store the zero terminator at the end of the cstring	sep #$20	;put into 8-bit a-reg. mode	longa off	lda #0	sta [DP4],y	;store the zero terminator at the end	rep #$20	;back into 8-bit a-reg. mode	longa on	PushLong MyNewHandle	_HUnLock	;unlock the handle	bcs FinishUp	;branch if any error			;Now we need to remove any old program that might exist	PushWord #$801D	;rCString	PushLong #1	;resource ID=1	_RemoveResource	;this removes any existing resource;Note: we dont care if we get an error, we just want to make sure the resorce;has been removed so we can add the new one to it.;OK, now we have the data in the handle so we can creat a resource with it	PushLong MyNewHandle ;handle of data for resource	PushWord #$0000	;attributes of resource	pushword #$801D	;resource type	pushlong #1	;resource ID	_AddResource			;Now just finish things upFinishUp	pha	;save error no	jsr RShutDown	;shut down the resource stuff	bcc NoSDErr	;branch if no shut down error	plx	cpx #0	beq OutOfHere	;branch if no error before shutdown (return shutdown error)	txa	;get old error number	bra OutOfHere	;else return error before shutdown errorNoSDErr	plaOutOfHere	jmp Exit8			MyDiscTitle	dc.l 0	;pointer to passed stringMyStrLength	dc.l 0	;length of data string (want long, zeros for high word)MyNewHandle	dc.l 0	;created handle	ENDP****************************************************************** MCGetErrorMsg**     ** Returns a P-string description of the media control error passed*****************************************************************	EXPORT MCGetErrorMsgMCGetErrorMsg	PROC	definestackDPFrame	Block DirectStack	;direct page stack frameOrigB	byteOrigD	wordRTL1	block 3RTL2	block 3ReturnStr	LONG	;resultant string ptrPassedErr	word	;passed error no.	jsr SetupFrame	;setup direct page stack frame;Now get the passed error number and see if its one of ours	lda PassedErr,s	sta ErrorBack	;save as error back value	cmp #$2600	bcc NotMyErr	;branch if less than tool038	cmp #$2700	bcs NotMyErr	;branch if greater than tool038;;We arrive here is its a Tool038 error $2600-26ff;GeneralErr	and #$00ff	;mask out unwanted tool no.	asl a	cmp StrTableLen	;now see if we have a message in table	bcc GotGoodErr	;branch if message in tableNotMyErr	lda #0	;default to err00	bra GotBadErr	;branch so will return same error back;Get the source address of string (the errors string description)GotGoodErr		stz ErrorBack	;clear error back routineGotBadErr	tax	;save index into table in x-reg.	lda #^StrTable	;get strings bank	pha	lda StrTable,x	;get address of string (low word)	pha	DEFINESTACKSourceAddr	LONG	ldy #0	lda (SourceAddr,s),Y ;get the length of string	and #$00ff	tax	;save length in x-reg.	inx	;inc. by one for length byte;Get the destiniation from the passed RetName	lda ReturnStr+6,s	pha	lda ReturnStr+6,s	pha;Now get the no. of bytes from the string	lda #0	pha	phx	;push length of string	_blockmove	;move it	ErrorOut			lda ErrorBack	JustOut	brl Exit6;;This is a table of WORD pointers to the error P-string descriptions;StrTable	dc.w Err00	dc.w Err01	dc.w Err02	dc.w Err03	dc.w Err04	dc.w Err05	dc.w Err06	dc.w Err07	dc.w Err08	dc.w Err09	dc.w Err0a	dc.w Err0b	dc.w Err0c	dc.w Err0d	dc.w Err0e	dc.w Err0f	dc.w Err10	dc.w Err11	dc.w Err12	dc.w Err13StrTableLen	dc.w (StrTableLen-StrTable);; These are the actual error description p-strings;Err00	str 'No message available for this error.'Err01	str 'Unimplemented for this device.'Err02	str 'Invalid speed specified.'Err03	str 'Invalid unit type specified.'Err04	str 'Timed out during device read.'Err05	str 'No media control driver loaded.'Err06	str 'Invalid audio selector value specified.'Err07	str 'Device returned error (unable to perform).'Err08	str 'Unrecognizable status from device.'Err09	str 'Invalid selector value specified.'Err0a	str 'Unrecognizable data received (try again).'Err0b	str 'Invalid port specified.'Err0c	str 'Scans only once.'Err0d	str 'Resource manager not active.'Err0e	str 'Item not found in database.'Err0f	str 'Tool038 was already shutdown.'Err10	str 'Tool038 was already started.'Err11	str 'Invalid channel number.'Err12	str 'Invalid parameter specified.'Err13	str 'Invalid Media Control Tool call.'ErrorBack	ds.w 1	;error returned back if no message found	ENDP;-------------------------------------------------------------------;;  NAME:	MCCvtTime2Bin;;  PURPOSE:	To convert a BCD time value to a binary equivalent value.;	Long of HHMMSSFF BCD to Long binary value.;;  PASSED:	LONG PassedBCD 	;BCD time value to convert;;  RETURNED:	LONG ReturnBin 	;Returned binary value;;-------------------------------------------------------------------	EXPORT MCCvtTime2BinMCCvtTime2Bin 	PROC				definestackDPFrame	Block DirectStack	;direct page stack frameOrigB	byteOrigD	wordRTL1	block 3RTL2	block 3PassedBCD	LONG	;passed BCD valueReturnBin	LONG	;resultant binary value	jsr SetupFrame	;setup direct page stack frame	lda PassedBCD,s	;get BCD time value	sta MyBCDTime	;init.	lda PassedBCD+2,s	sta MyBCDTime+2	;First we'll expand the the BCD value to an ASCII string	sep #$30				;set to 8-bit mode	longa off	longi off	lda #8	sta BCDScratchStr	;init. string byte count				ldx #8					;init. index into string	ldy #0LoopBytes;First do low bcd digit of byte	lda MyBCDTime,y	and #$0f	ora #$30				;make ascii	sta BCDScratchStr,x	dex;Now do high bcd digit of byte	lda MyBCDTime,y	lsr A	lsr A	lsr A	lsr A	ora #$30				;make ascii	sta BCDScratchStr,x	dex	iny	cpy #4	bcc LoopBytes;At this point BCDScratchStr has the ascii string HHMMSSFF	longa on	longi on	rep #$30				;set 16-bit mode				pha	;space for result						;space for result	pha	PushLong #BCDScratchStr+1  ;(one past length byte)	PushWord #8	;length of string	PushWord #0	;not signed	_Dec2Long	;convert to decimal		bcc OKData	;branch if no errors	plx	;get rid of returned value	plx	bra Finish;We arrive here with no errorsOKData	ply						;get low word of long	pla	;get high word of long	sta ReturnBin+2,s	tya	sta ReturnBin,s	lda #0	;return no errorsFinish	jmp Exit4			MyBCDTime	dc.l	0	;storage space for BCD TimeBCDScratchStr	ds.b	10	;space for intermediat string	ENDP;-------------------------------------------------------------------;;  NAME:	MCCvtBin2Time;;  PURPOSE:	To convert a binary time value to a BCD equivalent value.;	Long binary value to Long HHMMSSFF BCD value.;;  PASSED:	LONG PassedBCD 	;Binary value to convert;;  RETURNED:	LONG ReturnedBCD 	;Returned HHMMSSFF BCD value;;-------------------------------------------------------------------	EXPORT MCCvtBin2TimeMCCvtBin2Time 	PROC	definestackDPFrame	Block DirectStack	;direct page stack frameOrigB	byteOrigD	wordRTL1	block 3RTL2	block 3PassedBCD	LONG	;passed Binary Time valueReturnBCD	LONG	;resultant BCD Time value	jsr SetupFrame	;setup direct page stack frame	lda PassedBCD+2,s	;get passed BCD value (high word)	pha	;pass for long value to convert	lda PassedBCD+2,s	;get passed BCD value (low word)	pha	PushLong #BinaryStr+1  ;ptr to where to put string	PushWord #8				;length of buffer	PushWord #0				;flag indicating not signed value	_Long2Dec				;convert to ascii string;Now convert ascii to BCD HHMMSSFF				sep #$30				;set to 8-bit mode	longa off	longi off	lda #8	sta BinaryStr	;init. string byte count				ldx #8					;init. index into string	ldy #0LoopBytes;First do low bcd digit of byte	lda BinaryStr,x	;get ascii digit	and #$0f				;make binary	sta TimeVal,y	dex;Now do high bcd digit of byte	lda BinaryStr,x	and #$0f	asl A	asl A	asl A	asl A	ora TimeVal,y	;or with lsbyte	sta TimeVal,y	dex	iny	cpy #4	bcc LoopBytes	longa on	longi on	rep #$30	;back to 16-bits				;set 16-bit mode;Now finish up and set the return BCD value	lda TimeVal	sta ReturnBCD,s	lda TimeVal+2	sta ReturnBCD+2,s	lda #0	jmp Exit4			BinaryStr	ds.b 12	;room for ascii binary string of timeTimeVal	ds.L 1			ENDP	******************************************************************* Calls passed on to drivers!******************************************************************	EXPORT PassPass	PROC	;----------------------------------------------------------------------;; These calls are passed on to the current media device driver.;;----------------------------------------------------------------------;------------------------------------------------------------; mcGetName;------------------------------------------------------------	EXPORT mcGetNamemcGetName	definestack	block 4	;source addr.	block 2	;asave	block 3	;rtl2	block 3	;rtl1NAddr	block 4;First lets set the default name in case we don't have a connection	pha	;save a-reg.	PushLong #DefaultStr	lda NAddr+2,s	pha	lda NAddr+2,s	pha	PushLong #19	_blockmove	pla	;restore a-reg.		ldx #omcGetName	jmp Dispatch4DefaultStr	str 'MCToolkit NoPlayer';------------------------------------------------------------; mcDStartUp;------------------------------------------------------------	EXPORT mcDStartUpmcDStartUp		ldx #omcDStartUp	jmp Dispatch6;------------------------------------------------------------; mcDShutDown;------------------------------------------------------------	EXPORT mcDShutDownmcDShutDown		ldx #omcDShutDown	jmp Dispatch0;------------------------------------------------------------; mcGetFeatures;------------------------------------------------------------	EXPORT mcGetFeaturesmcGetFeatures		ldx #omcGetFeatures	jmp Dispatch2	;------------------------------------------------------------; mcPlay;------------------------------------------------------------	EXPORT mcPlaymcPlay		ldx #omcPlay	jmp Dispatch0	;------------------------------------------------------------; mcPause;------------------------------------------------------------	EXPORT mcPausemcPause		ldx #omcPause	jmp Dispatch0	;------------------------------------------------------------; mcSendRawData;------------------------------------------------------------	EXPORT mcSendRawDatamcSendRawData	ldx #omcSendRawData	jmp Dispatch4	;------------------------------------------------------------; mcGetStatus;------------------------------------------------------------	EXPORT mcGetStatusmcGetStatus	ldx #omcGetStatus	jmp Dispatch2	;------------------------------------------------------------; mcControl;------------------------------------------------------------	EXPORT mcControlmcControl	ldx #omcControl	jmp Dispatch2	;------------------------------------------------------------; mcScan;------------------------------------------------------------	EXPORT mcScanmcScan	ldx #omcScan	jmp Dispatch2	;------------------------------------------------------------; mcGetSpeeds;------------------------------------------------------------	EXPORT mcGetSpeedsmcGetSpeeds	ldx #omcGetSpeeds	jmp Dispatch4	;------------------------------------------------------------; mcSpeed;------------------------------------------------------------	EXPORT mcSpeedmcSpeed	ldx #omcSpeed	jmp Dispatch2	;------------------------------------------------------------; mcStopAt;------------------------------------------------------------	EXPORT mcStopAtmcStopAt	ldx #omcStopAt	jmp Dispatch6	;------------------------------------------------------------; mcJogN;------------------------------------------------------------	EXPORT mcJogNmcJogN	ldx #omcJogN	jmp Dispatch8	;------------------------------------------------------------; mcSearchTo;------------------------------------------------------------	EXPORT mcSearchTomcSearchTo	ldx #omcSearchTo	jmp Dispatch6	;------------------------------------------------------------; mcSearchDone;------------------------------------------------------------	EXPORT mcSearchDonemcSearchDone	ldx #omcSearchDone	jmp Dispatch0	;------------------------------------------------------------; mcSearchWait;------------------------------------------------------------	EXPORT mcSearchWaitmcSearchWait	ldx #omcSearchWait	jmp Dispatch0	;------------------------------------------------------------; mcGetPosition;------------------------------------------------------------	EXPORT mcGetPositionmcGetPosition	ldx #omcGetPosition	jmp Dispatch2	;------------------------------------------------------------; mcSetAudio;------------------------------------------------------------	EXPORT mcSetAudiomcSetAudio	ldx #omcSetAudio	jmp Dispatch2	;------------------------------------------------------------; mcSetVolume;------------------------------------------------------------	EXPORT mcSetVolumemcSetVolume	ldx #omcSetVolume	jmp Dispatch4	;------------------------------------------------------------; mcGetTimes;------------------------------------------------------------	EXPORT mcGetTimesmcGetTimes	ldx #omcGetTimes	jmp Dispatch2		;------------------------------------------------------------; mcGetNoTracks;------------------------------------------------------------	EXPORT mcGetNoTracksmcGetNoTracks	ldx #omcGetNoTracks	jmp Dispatch0		;------------------------------------------------------------; mcGetDiscTOC;------------------------------------------------------------	EXPORT mcGetDiscTOCmcGetDiscTOC	ldx #omcGetDiscTOC	jmp Dispatch2	;------------------------------------------------------------; mcGetDiscID;------------------------------------------------------------	EXPORT mcGetDiscIDmcGetDiscID	ldx #omcGetDiscID	jmp Dispatch0	;------------------------------------------------------------; mcRecord;------------------------------------------------------------	EXPORT mcRecordmcRecord	ldx #omcRecord	jmp Dispatch0	;------------------------------------------------------------; mcStop;------------------------------------------------------------	EXPORT mcStopmcStop	ldx #omcStop	jmp Dispatch0	;------------------------------------------------------------; mcWaitRawData;------------------------------------------------------------	EXPORT mcWaitRawDatamcWaitRawData	ldx #omcWaitRawData	jmp Dispatch8;------------------------------------------------------------;------------------------------------------------------------; Dispatch0;------------------------------------------------------------;------------------------------------------------------------Dispatch0	definestack	block 2	;asave	block 3	;rtl2	block 3	;rtl1McChann0	word	pha	lda McChann0,s	;get media channel no.	tay	pla	jmp Dispatch;------------------------------------------------------------;------------------------------------------------------------; Dispatch2;------------------------------------------------------------;------------------------------------------------------------Dispatch2	definestack	block 2	;asave	block 3	;rtl2	block 3	;rtl1	block 2McChann2	word	pha	lda McChann2,s	;get media channel no.	tay	pla	jmp Dispatch;------------------------------------------------------------;------------------------------------------------------------; Dispatch4;------------------------------------------------------------;------------------------------------------------------------Dispatch4	definestack	block 2	;asave	block 3	;rtl2	block 3	;rtl1	block 4McChann4	word	pha	lda McChann4,s	;get media channel no.	tay	pla	jmp Dispatch;------------------------------------------------------------;------------------------------------------------------------; Dispatch6;------------------------------------------------------------;------------------------------------------------------------Dispatch6	definestack	block 2	;asave	block 3	;rtl2	block 3	;rtl1	block 6McChann6	word	pha	lda McChann6,s	;get media channel no.	tay	pla	jmp Dispatch;------------------------------------------------------------;------------------------------------------------------------; Dispatch8;------------------------------------------------------------;------------------------------------------------------------Dispatch8	definestack	block 2	;asave	block 3	;rtl2	block 3	;rtl1	block 8McChann8	word	pha	lda McChann8,s	;get media channel no.	tay	pla	jmp Dispatch	ENDP******************************************************************* Dispatch** Dispatches control to the Media Control driver.******************************************************************	EXPORT DispatchDispatch	PROC;NOTE:  Take care when adding or subtracting things that might affect the stack;When we get here, the y-reg. has the vector offset	pha	; get 3 bytes on stack for final rtl	phb	jsr SetupFrame	;setup direct page stack frame		pha	; save a-reg	phx	; save x-reg. (Call displacement no.)	phy	; save y-reg. (Media Channel No.)		;Multimedia channel stuff	tya	;get media channel no.	dec a	;dec. so will be zero base	sta MChannel	;save it	asl a	;times 2	sta MChannel2	;save times 2	asl a	sta MChannel4	;save times 4	ldx MChannel;Now check to see if media channel no. is withing range	cpx #MaxChannelNo	;see if greater than max. channel no.,	bcc OkChannNo	;branch if OK	ldx #BadChannel	;return bad channel error	stx DriverError	jmp ErrorDispatchOKChannNo	;Check to see if the driver has already been loaded	ldx MChannel2	lda MediaDriverID,x	bne NoDeviceChg;We arrive here if the driver hasn't previously been loaded	pha 	;space for result	pha 	_GetCursorAdr	; save current cursor		jsr WaitCursor	;set cursor to wait cursor	;Now attempt to load the driver	jsr loadCurMediaDriver ;attempt to load the driver	sta DriverError	;set error (if any occured)	_SetCursor	; restore original cursor using stuff on stack	lda DriverError	bne ErrorDispatch	;branch if error occured	;If everything loaded ok, then Startup the driver		definestackXTheChannNo	word	;media channel no.		lda XTheChannNo,s	pha	;first pass to MCDStartUp the media channel no.	dec a	;dec. so will be zero base	asl a	asl a	;times 4 (for referenceing table of longs)	tax	lda CDaddr+2,x	;pass high word of ports long addr	pha	lda CDaddr,x	;pass low word of port name	pha	ldx MChannel2	lda MediaDriverID,x	pha	;pass the drivers UserID	ldx #$1426	jsl >$E10000	;perform MCDStartUp;	_MCDStartUp	;perform device startup	sta DriverError	bcs ErrorDispatch	;branch if error occured	NoDeviceChg		lda MChannel4	tax	lda DispatchAdr+2,x	sta Temp1+2	lda DispatchAdr,x	sta Temp1	;The following checks call no. against drivers call table length.	ldy #2	; check the call count	lda [Temp1],y	dec a	; subtract 1 since the index begins with 0	asl a	asl a	; 4 bytes per address entry from jump table		definestackTheChannNo	wordCallDispNo	word	cmp CallDispNo,s	blt CallNotSupp		GoDispatchNew	lda Temp1	clc	adc #4	; new drivers has jmp table 4 bytes from start	sta Temp1	bra GoDispatchCallNotSupp		lda #CallNotSupported	sta DriverError	;DDH We arrive here if we have an error; we dispatch to the dummy driver to handle call & params.ErrorDispatch	lda #DummyDriver	sta Temp1	lda #^DummyDriver	sta Temp1+2	;-----------------------------------------------------------;; GoDispatch	definestackysave	word	;Media Channel No.xsave	word	;Call displacement no.)asave	worddpFrame	block DirectStackbsave	bytedsave	wordrtladr	block 3	lda Temp1+1	sta rtladr+1,s	lda Temp1	dec a	sta rtladr,s			ply	; get y back (Media Channel No.)	plx	; get x-reg. back (Call displacement no.)	pla	; get a back;releases DirectStack bytes from stack	tsc							;get stack value	clc	adc #DirectStack	;release bytes	tcs	plb	pld	rtl	; dispatch	ENDP	******************************************************************** SetCurMediaDriver** CurMediaDriver is set to the currently selected driver for the* currently selected media channel.*******************************************************************	EXPORT SetCurMediaDriverSetCurMediaDriver	PROC	lda >MChannel4	tax	lda >CP2Addr+2,x	pha	lda >CP2Addr,x	pha	PushLong #CurMediaDriver	jsr CopyString	rts	ENDP******************************************************************** SetCurrentDriver** CurrentDriver is set to the currently selected port driver for the* currently selected media channel.*******************************************************************	EXPORT SetCurrentDriverSetCurrentDriver	PROC	lda >MChannel4	tax	lda >CDAddr+2,x	pha	lda >CDAddr,x	pha	PushLong #CurrentDriver	jsr CopyString	rts	ENDP******************************************************************** LoadCurMediaDriver** Loads the current	media driver.  Builds the path name we* want and then calls LoadSomething which returns the userid* in the a-register.  Returns address in x-reg and y-reg.*******************************************************************	EXPORT LoadCurMediaDriverLoadCurMediaDriver	PROC	jsl ReadSetupFile	; find out what user had picked	bcc GotSetupOK	;branch if read setup file OK	jmp MediaDevError	;DDH else return with error	GotSetupOK	jsr SetCurMediaDriver; set the internal data structures accordingly;;;;;;;;;;;;;;;;;This checks to see if there wasnt a driver name specified (speeds things up a bit)	lda CurMediaDriver	and #$00ff		;look only at length byte	beq PR2;;;;;;;;;;;;;;;;	PushLong #DriverSubPath	PushLong #PathBuffer	jsr CopyString	PushLong #PathBuffer	PushLong #CurMediaDriver	jsr AppendString	jsr LoadSomething	sta DriverError		;DDH Added		bcs PR3		phx	pha	lda >MChannel2	tax	pla	sta >MediaDriverID,x	lda >MChannel4	tax	pla		;restore x-reg into a-reg.	sta >DispatchAdr,x	tya	sta >DispatchAdr+2,x	PushLong #CurMediaDriver	PushLong #DriverInMem	jsr CopyString	lda #0	sta DriverError	clc	rtsMediaDevErrorPR1PR2PR3	phx		;save x-reg.			ldx MChannel2	lda #0		;zero out ID	sta MediaDriverID,x		ldx MChannel4	lda #DummyDriver	sta DispatchAdr,x	lda #^DummyDriver	sta DispatchAdr+2,x	lda #MissingDriver	sta DriverError	plx		;restore x-reg.	sec		;return with error	rts	ENDP******************************************************************** LoadSomething** Loads the driver who's path name is in the path buffer* Returns the UserID in a-reg and address of what was loaded* in x-reg and y-reg.*******************************************************************	EXPORT LoadSomethingLoadSomething	PROC;First do a GetFileInfo to see if the volume is online and the file with that name is there	_GetFileInfo FIParams	bcs CheckForVol;Now lets make sure that the file type and aux type are valid media ctrl driver types.	lda FIType	;get file type	cmp #FileTypeMC	;is it a driver?	bne NoGoodFile	;branch if not		lda FIAuxType	;get files aux type	and #$ff00	;mask for media ctrl type	cmp #AuxTypeMC	;is it media ctrl type?	beq GoodFile	;branch if correct;We arrive here if its a bad file or aux typeNoGoodFile	lda #MissingDriver	;file not found (missing driver) error	sec	rts	;Now we are confident its a good file and we can go ahead and load it in.GoodFile	PushWord #0	; Returned: dir/page stack size	PushWord #0	; Returned: dir/page stack loc	PushLong #0	; Returned: starting address	PushWord #0	; Returned: UserID assigned.	PushWord #0	; Passed: UserID to use (for now let loader;		; assign one.	PushLong #PathBuffer ; Passed: pointer to path	PushWord #0	; Passed: Not Special memory flag	_initialLoad	bcs ErrorOnLoad	pla	; get userid in a-reg	plx	; adr in x and y	ply	sta 3,s	; overstore the last piece of	pla	; useless info and get	pla	; user id back	rts	; carry is clear when get hereErrorOnLoad	plx	; remove space for id	plx	; remove space for addr	plx	plx	; remove directpage	loc	plx	; remove direct page sizeCheckForVol	cmp #VolumeNotFound	bne NotMissingDisk	jsr InsertDisk	bcc LoadSomething	bra NoGoodFile	;branch if hit cancle buttonNotMissingDisk	sec	rtsFIParams	DC.L PathBuffer	;address of files pathFIAccess	dc.w 0	;file accessFIType	dc.w 0	;file type areaFIAuxType	dc.l 0	;file aux type area	DS.B 14	;the rest we don't care about	ENDP******************************************************************** UnloadCurMediaDriver** This routine unloads a media driver.* PASSED:*      (A-reg.)	=0	;unload and purge driver and userid*	=1	;make driver restartable*******************************************************************	EXPORT UnLoadCurMediaDriverUnLoadCurMediaDriver PROC	sta UserSDownFlag		lda MChannel2	tax	lda >MediaDriverID,x	beq NoDriverLoaded;First shutdown the driver before we unload it	txa	lsr a	;divide by two	inc a	;make 1-8 based	pha	;pass media channel no.	ldx #$1526	jsl >$E10000	;perform MCDShutdown on the driver;	_MCDShutdown	;perform device shutdown	lda MChannel2	tax	lda MediaDriverID,x	;get drivers userID;Now Unload the driver		PushWord #0	pha	;pass userID	PushWord UserSDownFlag ;make restartable or purge	_userShutdown	plx	;returned userid of driver (not needed)	bcc PrDriverUnloaded	pha	; save result of _usershutdown call call	ldx MChannel4	lda #DummyDriver	sta DispatchAdr,x	lda #^DummyDriver	sta DispatchAdr+2,x	lda #MissingDriver	sta DriverError	ldx MChannel2	lda #0	sta MediaDriverID,x	pla	; restore result of	loader call	bra NoDriverLoadedPrDriverUnloaded	lda #0	ldy UserSDownFlag	;get restart flag	bne NoDriverLoaded	;branch if want restartable	ldx MChannel2	sta MediaDriverID,x ;set driver id to zero	sta DriverInMemNoDriverLoaded	rtsUserSDownFlag	dc.w 1	;user shutdown flag (normally 1 for restartable)	ENDP******************************************************************** DriverChanges** Return carry set if the Current driver string is not equal* to the driver in memory string.*******************************************************************	EXPORT DriverChangesDriverChanges	PROC	PushLong #CurMediaDriver	PushLong #DriverInMem	jsr EqualString	beq same	sec	rtsSame	clc	rts	EXPORT DidPortChangeDidPortChange		       	PushLong #CurrentDriver	PushLong #PortInMem	jsr EqualString	beq Same	sec		rts	ENDP******************************************************************** ReadSetupFile** Reads the setup file if there is one.	 If there is not a setup it creates a blank one* If the number of bytes to read in does not equal the number of bytes actually* read the media.setup file file format is not compatible.*******************************************************************	EXPORT ReadSetupFileReadSetupFile	PROCCreateNewSetup	jsr OpenSetup	bcs GotError	;DDH branch if unable to read setup	_READ ReadSetupParams	bcs ReadOK	_Get_EOF GetEOFParams	lda SizeOfFile	cmp #EndSetupFileInfo-SetupFileInfo	beq ReadOK;	jsr CloseSetup;	_DESTROY DestroyParams;	bra CreateNewSetupReadOK	jsr CloseSetup	lda #0	;DDH return no errors	clc	;DDHGotError	rtl	ENDP******************************************************************** WriteSetupFile** Writes the setup file information back out to the system disk.*******************************************************************	EXPORT WriteSetupFileWriteSetupFile	PROC	_OPEN OpenSetupParams	bcs GotError	lda OpenSetupID	sta ReadSetupID	sta WriteSetupID	sta CloseSetupIDDoWrite	_WRITE WriteSetupParams	bcc NoErrDoAlert	PushWord #1	; show message #1 ('Changes made to the Choose	jsl PostAlert	; Printer dialog could not be saved to disk.')	pla	; get data back off	from the stackNoErr	jsr CloseSetup	rtlGotError	cmp #FileNotFound	; do we need to create a printer.setup file?	beq CreateNewFile		cmp #VolumeNotFound	; if volume not found then put up 'Insert disk...'	beq PutUpInsertDLog	; message	bra DoAlert	CreateNewFile	_Create CreateSetupParams ; create new file, if error then put up	bcs DoAlert	; alert saying no changes could be saved.			bra WriteSetupFile	; else open new file and write out the changes.	PutUpInsertDLog	jsr InsertDisk	bcc WriteSetupFile	bcs DoAlert		ENDP******************************************************************** OpenSetup** Opens the setup file on system disk for reading or writing.*******************************************************************	EXPORT OpenSetupOpenSetup	PROC;First set the prefix 8 (for networked booting to look in users directory.)	jsr MySetPrefix	;go set prefix 8	_OPEN OpenSetupParams	bcs Error	lda OpenSetupID	sta ReadSetupID	sta WriteSetupID	sta CloseSetupID	sta GetEOFID	rtsError	cmp #FileNotFound	beq MakeFile	cmp #VolumeNotFound	beq InsertSkipThis	pha	;save error	jsr DefaultSetup	pla	;restore error	sec	rts;----------------------------------------------------------;; When I make a file I create it and then write the; default info into	it.;MakeFile		;	_Create CreateSetupParams	bcs SkipThis	jsr DefaultSetup	jsl WriteSetupFile	bra OpenSetup;----------------------------------------------------------;; Here I ask for disk insertion.  If user presses cancel; we skip this which gives us the default setup and; then quits.Insert	jsr InsertDisk	bcc OpenSetup	bcs SkipThis	ENDP******************************************************************** CloseSetup** Closes the setup file that was opened	earlier.*******************************************************************	EXPORT CloseSetupCloseSetup	PROC	_CLOSE CloseSetupParams	php	pha	_SetPrefixGS RestorePFix	;restore the prefix-8	pla	plp	rts	ENDP******************************************************************** DefaultSetup** This routine sets	up default SetupFile info for the case* where there is no	SetupFile to read or the disk is not around.** There are four things to setup:**     CurMediaDriver*     CurrentDriver	(Port)*     CurrentUser (name)*     CurrentNetName** Important:  This must be called after	the driver lists are* created.*******************************************************************	EXPORT DefaultSetupDefaultSetup	PROC	jsr DefaultPrinter	jsr DefaultPort	lda #0	; set the default screen to be	sta AppleTalkOn	; direct connect	lda NumPorts	; were there any port drivers found other 	bne SomeFound	; than AppleTalk	lda NoAppleTalk	; is the appletalk driver present	beq SomeFound	inc AppleTalkOn	; make the appletalk screen come up since there		; were no other port drivers found	SomeFound	sep #$30	longa off	longi off	ldx DefaultUserLoop3	lda DefaultUser,x	sta CurrentUser,x	dex	bpl Loop3	ldx DefaultNetNameLoop4	lda DefaultNetName,x	sta CurrentNetName,x	dex	bpl Loop4	ldx DefaultZoneNameLoop5	lda DefaultZoneName,x	sta CurrentZoneName,x	dex	bpl Loop5	rep #$30	longa on	longi on		rtsDefaultUser	str 'John Q. Public'DefaultNetName	str 'LASERWRITER'DefaultZoneName	str '*'	ENDP******************************************************************** DefaultPrinter** Puts the first printer in the printer	list into* CurMediaDriver.*******************************************************************	EXPORT DefaultPrinterDefaultPrinter	PROC	lda >NumPrinters	beq EmptyPrinterList		movelong PrinterList,Temp1	jsr DerefTemp1ToTemp2	clc	lda Temp2	adc #5	; 5 for list mgr	sta Temp2	bcc NoCarry1	inc Temp2+2NoCarry1		;	sep #$30	longa off	longi off	lda [Temp2]	tayLoop1	lda [Temp2],y	sta CurMediaDriver1,y ; first printer type in list is default	sta CurMediaDriver2,y ; for AT and DC selections	dey	bpl Loop1	rep #$30	longa on	longi on	rtsEmptyPrinterList	lda #0	sta CurMediaDriver1	sta CurMediaDriver2	 	rts		ENDP******************************************************************** DefaultPort** Puts the first Port in the port list into* CurrentDriver*******************************************************************	EXPORT DefaultPortDefaultPort	PROC	lda >NumPorts	beq EmptyPortList		movelong PortList,Temp1	jsr DerefTemp1ToTemp2	clc	lda Temp2	adc #5	; 5 for list mgr	sta Temp2	bcc NoCarry2	inc Temp2+2NoCarry2		;	sep #$30	longa off	longi off	lda [Temp2]	tayLoop2	lda [Temp2],y	sta CurrentPort,y	dey	bpl Loop2	rep #$30	longa on	longi on	rtsEmptyPortList	lda #0	sta CurrentPort		rts		ENDP******************************************************************** PostAlert** Puts up alert box	for what ever error	has occurred that needs to* be brought to the	user's attention.*******************************************************************	EXPORT PostAlertPostAlert	PROC	defineStackOrigCursor	longOrigB	byteOrigD	wordRTLAdr	block 3Message	word	phb	phd	phk	plb		pha	; save original cursor	pha	_GetCursorAdr		tsc	tcd	jsr InitCursor	; restore cursor back to arrow	pha	; make room for result	_GetMasterSCB	pla	pha	; make room for result of alert call	and #$80	; check mode	beq mode320	; 320 mode	pushlong #alerttemp640 ; use 640 mode template	lda Message	asl a	tax	jmp (LoadMessage640,x)LoadMessage640	DC.W 0	DC.W NoPortMessage640	DC.W CantFindDrvr640NoPortMessage640	lda #Msg1_640	ldx #^Msg1_640+2	ldy #EndMsg1_640-Msg1_640	bra StoreValues640CantFindDrvr640	lda #Msg2_640	ldx #^Msg2_640+2	ldy #EndMsg2_640-Msg2_640StoreValues640	sta WhatMessage640	stx WhatMessage640+2	sty MessLength640	bra GoOnmode320	pushlong #alerttemp320 ; use 320 mode template	lda Message	asl a	tax	jmp (LoadMessage320,x)LoadMessage320	DC.W 0	DC.W NoPortMessage320	DC.W CantFindDrvr320NoPortMessage320	lda #Msg1_320	ldx #^Msg1_320+2	ldy #EndMsg1_320-Msg1_320	bra StoreValues320CantFindDrvr320	lda #Msg2_320	ldx #^Msg2_320+2	ldy #EndMsg2_320-Msg2_320	StoreValues320	sta WhatMessage320	stx WhatMessage320+2	sty MessLength320GoOn	pushlong #$0000	_StopAlert	pla	; get the item hit off stack	_SetCursor	; restore cursor		plb	pld	rtl	ENDP******************************************************************* SetupDriverLists** Makes the ProDOS call GetDirEntry and	finds all the port and printer* drivers in the */system/drivers folder.  The values NumPrinters and* NumPorts are incremented respectively	each time a driver is found.** When a driver is found it is either put into the PrinterList or PortList* to be used later by the list manager for displaying in the Choose Printer* dialog.******************************************************************	EXPORT SetUpDriverListsSetUpDriverLists	PROC	stz PrinterListSize	stz PortListSize	lda #ListEntrySize*10 ; enough for 10 entries	jsr GetMem	bcc NoErr0	brl ErrorNoErr0	sta PrinterList	stx PrinterList+2	lda #ListEntrySize*10 ; enough for 10 entries	jsr GetMem	bcc NoErr1	brl ErrorNoErr1	sta PortList	stx PortList+2OpenAgain	_Open OpenParams	bcc OpenOK	brl ErrorOpenOK	lda OpenID	sta GetDirID	sta CloseIDNextEntry	_Get_Dir_Entry GetDirParams	bcs Done	lda Length	xba	sta Length	lda EntryName	; is this a real entry?	and #$00FF	beq NextEntry	lda EntryType	; is this a driver file?	and #$00FF	cmp #$00BB	bne NextEntry	lda EntryAuxType	cmp #$0001	; is it a printer driver?	bne NotPrinter	inc NumPrinters	jsl InsertPrinterList	bra NextEntryNotPrinter	cmp #$0002	; is it a port driver?	bne NotPortDrvr	inc NumPorts	jsl InsertPortList	bra NextEntryNotPortDrvr	cmp #$0003	; is it the AppleTalk Driver?	bne NextEntry	inc NoAppleTalk	PushLong #EntryName	PushLong #AppleTalkStr	jsr CopyString	bra NextEntryDone	_Close CloseParams	lda #0	clc	rtlError	pha	; save error returned on stack	jsr DisposePrinterList	jsr DisposePortList	pla	; get error back from stack	sec	rtl	ENDP******************************************************************* InsertPrinterList******************************************************************	EXPORT InsertPrinterListInsertPrinterList	PROC	movelong PrinterList,Temp1	lda PrinterListSize	sta ListSize	clc	adc #ListEntrySize	sta PrinterListSize	bra InsertInList	EXPORT InsertPortListInsertPortList		;       	movelong PortList,Temp1	lda PortListSize	sta ListSize	clc	adc #ListEntrySize	sta PortListSizeInsertInList		;	jsr DerefTemp1ToTemp2	pha	pha	PushLong Temp1	_GetHandleSize	pla	plx	cmp ListSize	beq NoRoom	bcs ThereIsRoomNoRoom	clc	adc #2*ListEntrySize ; create enough space for 2 more drivers	phx	pha	PushLong Temp1	_SetHandleSize	jsr DerefTemp1ToTemp2ThereIsRoom		;	lda EntryName	and #$000F	tax	clc	adc ListSize	adc #5	tay	sep #%00100000	longa offNameLoop		;	lda EntryName,x	sta [Temp2],y	dey	dex	bne NameLoop	lda EntryName	and #$0F	sta [Temp2],y	dey	; now zero out the memflag byte.	lda #0	sta [Temp2],y	rep #%00100000	longa on	rtl	ENDP******************************************************************* DerefTemp1ToTemp2******************************************************************	EXPORT DerefTemp1ToTemp2DerefTemp1ToTemp2	PROC	lda [Temp1]	sta Temp2	ldy #$0002	lda [Temp1],y	sta Temp2+2	rts	ENDP******************************************************************* GetMem******************************************************************	EXPORT GetMemGetMem	PROC	pha	; space for result.	pha	pea 0	; block size	pha	PushWord UserID	; Owner.	PushWord #00	; no restrictions	pha	; invalid loc info	pha	_NewHandle	bcs AnError	pla	plx	rtsAnError	plx	plx	rts	ENDP;                copy    utils.asm******************************************************************** EqualString**     Pointer1*     Pointer2** This returns result in zero flag:**    set if equal and*    clear if not equal*******************************************************************	EXPORT EqualStringEqualString	PROC	DefineStackOrigD	wordRTS	wordPtr1	LONGPtr2	LONG	phd	tsc	tcd	sep #$30	longa off	longi off	lda [Ptr1]	cmp [Ptr2]	bne NotEqual	tayCompareLoop		;	lda [Ptr1],y	jsr UpperCase	sta [Ptr1],y	lda [Ptr2],y	jsr UpperCase	cmp [Ptr1],y	bne NotEqual	dey	bpl CompareLoopEqual		;	rep #$30	longa on	longi on	pld	pla	plx	plx	plx	plx	pha	lda #0	rtsNotEqual		;	rep #$30	longa on	longi on	pld	pla	plx	plx	plx	plx	pha	rts;----------------------------------------------------------;; Uppercase routine;; runs in 8 bit mode.;	longa off	longi offUpperCase		;	cmp #'a'	bcc NoChange	cmp #'z'	bcc ChangeIt	beq ChangeItNoChange	rtsChangeIt	sec	sbc #$20	rts	longa on	longi on	ENDP****************************************************************** CopyString** Input : Pointer To Source String*       : Pointer to Dest String** Ouput : none*****************************************************************	EXPORT CopyStringCopyString	PROC	DefineStackOrigD	wordRTLAdr	wordDestPtr	LONGSrcPtr	LONG	phd	tsc	tcd	lda #0	sep #%00100000	longa off	lda [SrcPtr]	tayLoop	lda [SrcPtr],y	sta [DestPtr],y	dey	bpl Loop	rep #$30	longa on	longi on	pld	pla	plx	plx	plx	plx	pha	rts	ENDP****************************************************************** AppendString** Input : Pointer To Orig String*       : Pointer to New String** Ouput : none** New string is appended to orig string*****************************************************************	EXPORT AppendStringAppendString	PROC	DefineStackOrigD	wordRTLAdr	wordNewPtr	LONGOrigPtr	LONG	phd	tsc	tcd	sep #%00110000	longa off	longi off	lda [OrigPtr]	; get orig length and put in x	tax	ldy #$01	; start y at 1 for new stringLoop	tya	; See if we are done with new	cmp [NewPtr]	; string by comparing with length	beq OneMoreTime	bcs DoneOneMoreTime	lda [NewPtr],y	; now done so get next char	phy	; save y on stack	txy	; get pointer to last char in orig str	iny	; bump by 1	sta [OrigPtr],y	; store char in orig str	tyx	; put back in x	ply	; get index to new off stack	iny	; bump by 1 and try	again	bra LoopDone	txa	; now update new length pointer	sta [OrigPtr]	rep #$30	longa on	longi on	pld	pla	plx	plx	plx	plx	pha	rts	ENDP******************************************************************** Cursor Stuff** These are public entry points to these common routines that* are used so often	that it pays to have a simple jsr entry	point* to them rather than wasting 7 bytes every time they are called.*******************************************************************	EXPORT CursorStuffCursorStuff	PROC	EXPORT WaitCursorWaitCursor		;       	_WaitCursor	rts	EXPORT InitCursorInitCursor		;       	_InitCursor	rts	ENDP******************************************************************** DisposeStuff** Disposes the PrinterList handle and the PortList handle.*******************************************************************	EXPORT DisposeStuffDisposeStuff	PROC	EXPORT DisposePrinterListDisposePrinterList		;       	lda PrinterList	ora PrinterList+2	beq Done	PushLong PrinterList	_DisposeHandle	stz PrinterList	stz PrinterList+2Done	rts	EXPORT DisposePortListDisposePortList		;       	lda PortList	ora PortList+2	beq Done	PushLong PortList	_DisposeHandle	stz PortList	stz PortList+2	rts	ENDP******************************************************************** Exits*******************************************************************	EXPORT ExitExit	PROC	EXPORT Exit12Exit12		;       	jsr FreeFrame	;free the direct page stack frame	lda 5,s	sta 17,s	lda 3,s	sta 15,s	lda 1,s	sta 13,s	tsc	clc	adc #12	tcs	bra Exit0X	EXPORT Exit10Exit10		;       	jsr FreeFrame	;free the direct page stack frame	lda 5,s	sta 15,s	lda 3,s	sta 13,s	lda 1,s	sta 11,s	tsc	clc	adc #10	tcs	bra Exit0X	EXPORT Exit8Exit8		;       	jsr FreeFrame	;free the direct page stack frame	lda 5,s	sta 13,s	lda 3,s	sta 11,s	lda 1,s	sta 9,s	pla	pla	pla	pla	brl Exit0X	EXPORT Exit6Exit6		;       	jsr FreeFrame	;free the direct page stack frame	lda 5,s	sta 11,s	lda 3,s	sta 9,s	lda 1,s	sta 7,s	pla	pla	pla	brl Exit0X	EXPORT Exit4Exit4		;       	jsr FreeFrame	;free the direct page stack frame	lda 5,s	sta 9,s	lda 3,s	sta 7,s	lda 1,s	sta 5,s	pla	pla	brl Exit0X	EXPORT Exit2Exit2		;       	jsr FreeFrame	;free the direct page stack frame	lda 5,s	sta 7,s	lda 3,s	sta 5,s	lda 1,s	sta 3,s	pla	bra Exit0X	EXPORT Exit0Exit0 		jsr FreeFrame	;free the direct page stack frameExit0X	txa;Dec. busy flag because were not reentereant	pha	;save error for return	jsl DecBusyFlg	;dec. busy flag	pla	;restore error	cmp #1	Standard 0 byte input exit	rtl	ENDP******************************************************************** InsertDisk** This routine puts	up an insert system	disk dialog and allows* the user to press	OK or CANCEL.*******************************************************************	EXPORT InsertDiskInsertDisk	PROC	_GetBootVol BootVolParams	_ObscureCursor	pha	PushWord StartX	PushWord StartY	PushLong #InsertDiskStr	PushLong #VolNameStr	PushLong #OKButtonStr	PushLong #CancelButtonStr	_TLMountVolume	pla	cmp #1	bne Done	clcDone		rtsBootVolParams		;	DC.L VolNameStrVolNameStr	DS.B 16StartX	DC.W 10StartY	DC.W 25	ENDP******************************************************************* Hopefully, we will find a way to get rid of this.******************************************************************	EXPORT SillyDataSillyData	PROC	EXPORT DispatchAdrDispatchAdr		; this is address of the	DS.B 32	; media control driver in memory (4*8 MChannels)	EXPORT PrinterListPrinterList		; this is handle to list of	DS.B 4	; printers on disk	EXPORT PortListPortList		; this is handle to list of	DS.B 4	; ports on disk.	EXPORT PrinterHandlePrinterHandle		; handle to list of printer names	DS.B 4	EXPORT ZoneHandleZoneHandle		; handle to list of zone names	DS.B 4	ENDP******************************************************************* ReadDirData******************************************************************	EXPORT ReadDirDataReadDirData	PROC	EXPORT SavedZoneNameSavedZoneName	DS.B 33	EXPORT TempZoneTempZone	DS.B 33	EXPORT TempPrTypeTempPrType	DS.B 33	EXPORT TempNetNameTempNetName		;	EXPORT TempZone2TempZone2	DS.B 33	EXPORT WhereInModalWhereInModal	DC.W 0	EXPORT SomeThingFoundSomeThingFound	DC.W 0	EXPORT DefaultZoneDefaultZone	str '*'	EXPORT CurMediaDriverCurMediaDriver	DS.B 16		EXPORT CurrentDriverCurrentDriver	DS.B 16		EXPORT AppleTalkStrAppleTalkStr	DS.B 16	EXPORT NoAppleTalkNoAppleTalk	DS.B 2	EXPORT NumPrintersNumPrinters	DS.B 2	EXPORT NumPortsNumPorts	DS.B 2	EXPORT ListSizeListSize	DS.B 2	EXPORT PrinterListSizePrinterListSize	DS.B 2	EXPORT PortListSizePortListSize	DS.B 2	EXPORT OpenParamsOpenParams		;	EXPORT OpenIDOpenID	DC.W 00	; Refnumb output.	DC.L DirPath	; Pathname Pointer.	DC.L 00	; File's Buffer Output.	EXPORT CloseParamsCloseParams		;	EXPORT CloseIDCloseID	DS.B 2	EXPORT GetEOFParamsGetEOFParams		EXPORT GetEOFIDGetEOFID	DS.B 2	EXPORT SizeOfFileSizeOfFile	DC.L 00	; result, logical size of the file	EXPORT DirPathDirPath	str '*/system/drivers/Media.Control'	EXPORT DriverPathDriverPath	DS.B 40	EXPORT TheEntryTheEntry	DC.W $21	EXPORT LengthLength	DC.B 0	EXPORT EntryNameEntryName	DS.B 33	EXPORT GetDirParamsGetDirParams		;	EXPORT GetDirIDGetDirID	DC.W 00	; RefNumb	DC.W 00	; flags	DC.W 01	; base	DC.W 01	; displacement	DC.L TheEntry	; name of file	DC.W 00	; entry number	EXPORT EntryTypeEntryType	DC.W 00	; file type	DC.L 00	; eof	DC.L 00	; block count	DCB.B 8,00	; create time/date	DCB.B 8,00	; mod time/date	DC.W 00	; access attribute	EXPORT EntryAuxTypeEntryAuxType	DC.L 00	; auxiliary type field	DC.W 00	; file system identifier	EXPORT GetFileParamsGetFileParams		;	DC.L DriverPath	; pathname	DS.B 24	; result space	ENDP******************************************************************** SetupData** Data used for reading, writing and creating the setup file.*******************************************************************	EXPORT SetupDataSetupData	PROC	EXPORT CreateSetupParamsCreateSetupParams		;	DC.L SetupFileName	; Path pointer	DC.W $c3	; access bits	DC.W $5c	; file type	DC.L $00000100	; aux type	DC.W 1	; storage type (seedling)	DC.W 0	; create date	DC.W 0	; create time	EXPORT OpenSetupParamsOpenSetupParams		;	EXPORT OpenSetupIDOpenSetupID	DC.W 0	DC.L SetupFileName	DC.L 0	EXPORT ReadSetupParamsReadSetupParams		;	EXPORT ReadSetupIDReadSetupID	DC.W 0	DC.L CurMediaDriver1	DC.L EndSetupFileInfo-SetupFileInfo	EXPORT TransferCountTransferCount	DC.L 0	EXPORT WriteSetupParamsWriteSetupParams		;	EXPORT WriteSetupIDWriteSetupID	DC.W 0	DC.L CurMediaDriver1	DC.L EndSetupFileInfo-SetupFileInfo	DC.L 0	EXPORT CloseSetupParamsCloseSetupParams		;	EXPORT CloseSetupIDCloseSetupID	DC.W 0	EXPORT DestroyParamsDestroyParams		;	DC.L SetupFileName	EXPORT SetupFileNameSetupFileName	str '8/media.setup'	EXPORT SetupFileInfoSetupFileInfo		;	EXPORT CurMediaDriver1CurMediaDriver1		;	; printer driver selection for appletalk	DC.B 2,0		EXPORT CurMediaDriver2CurMediaDriver2		;	; printer driver selection for direct	DCB.B 33,0		; connect	DCB.B 231,0	EXPORT CurrentPortCurrentPort		;	; port driver selection	DCB.B 33,0	DCB.B 231,0	EXPORT CurrentUserCurrentUser		;       	DS.B 16	EXPORT CurrentNetNameCurrentNetName		;	; PrinterName+DeviceName+ZoneName	DS.B 33		; this name used to	open connection	EXPORT CurrentZoneNameCurrentZoneName		;       	DS.B 33	EXPORT AppleTalkOnAppleTalkOn		;	    ; AppleTalk or Direct Connect on	DS.B 2	; 0 is direct connect, 1 is appletalk	EXPORT EndSetupFileInfoEndSetupFileInfo		;;;Media Channel Offset tables;	EXPORT CP2AddrCP2Addr	DC.L CurMediaDriver2	;Media Channel 1	DC.L CurMediaDriver2+33	;Media Channel 2	DC.L CurMediaDriver2+2*33	;Media Channel 3	DC.L CurMediaDriver2+3*33	;Media Channel 4	DC.L CurMediaDriver2+4*33	;Media Channel 5	DC.L CurMediaDriver2+5*33	;Media Channel 6	DC.L CurMediaDriver2+6*33	;Media Channel 7	DC.L CurMediaDriver2+7*33	;Media Channel 8	EXPORT CDAddrCDAddr	DC.L CurrentPort		;Media Channel 1	DC.L CurrentPort+33		;Media Channel 2	DC.L CurrentPort+2*33	;Media Channel 3	DC.L CurrentPort+3*33	;Media Channel 4	DC.L CurrentPort+4*33	;Media Channel 5	DC.L CurrentPort+5*33	;Media Channel 6	DC.L CurrentPort+6*33	;Media Channel 7	DC.L CurrentPort+7*33	;Media Channel 8	ENDP******************************************************************** LoadData*******************************************************************	EXPORT LoadDataLoadData	PROC	EXPORT MediaDriverIDMediaDriverID	DCB.B  16,0		;8 MChannels times two bytes	EXPORT DriverErrorDriverError	DS.B 2	EXPORT DriverSubPathDriverSubPath	str '*/system/drivers/Media.Control/';	     12345678901234567	EXPORT PathBufferPathBuffer	DS.B 51	EXPORT DriverInMemDriverInMem	DS.B 16	EXPORT PortInMemPortInMem	DS.B 16	EXPORT MChannelMChannel	DS.B 2		;Media Channel No. (zero based)	EXPORT MChannel2MChannel2	DS.B 2		;Media Channel No. times 2	EXPORT MChannel4MChannel4	DS.B 2		;Media Channel No. times 4	ENDP******************************************************************* Dummy drivers to be installed after a	real driver is unloaded just* in case something	bad happens before an actual driver is loaded.** This is also used to clean up a call that doesn't load and start* the driver (an error is caused trying.)******************************************************************	EXPORT DummyDriverDummyDriver	PROC		jmp (ProcList,x)ProcList	DC.L Err6	; 0 MCGetName	DC.L Err8	; 1 MCDStartUp	DC.L Err2	; 2 MCDShutDown	DC.L Err4	; 3 MCGetFeatures	DC.L Err2	; 4 MCPlay	DC.L Err2	; 5 MCPause	DC.L Err6	; 6 MCSendRawData	DC.L Err4	; 7 MCGetStatus	DC.L Err4	; 8 MCControl	DC.L Err4	; 9 MCScan	DC.L Err6	;10 MCGetSpeeds	DC.L Err4	;11 MCSpeed	DC.L Err6	;12 MCStopAt	DC.L Err10	;13 MCJogN	DC.L Err8	;14 MCSearchTo	DC.L Err2	;15 MCSearchDone	DC.L Err2	;16 MCSearchWait	DC.L Err4	;17 MCGetPosition	DC.L Err4	;18 MCSetAudio	DC.L Err4	;19 MCGetTimes	DC.L Err4	;20 MCGetDiscTOC	DC.L Err2	;21 MCGetDiscID	DC.L Err2	;22 MCGetNoTracks	DC.L Err2	;23 MCRecord	DC.L Err2	;24 MCStop	DC.L Err10	;25 MCWaitRawData	DC.L Err6	;26 MCSetVolumeEndProcList		ENDP	EXPORT ErrsErrs	PROC	EXPORT Err0Err0		;       	jsr SetupFrame	;setup direct page stack frame	jsr ErrorExit	;unload driver if needed	brl Exit0	EXPORT Err2Err2		;       	jsr SetupFrame	;setup direct page stack frame	jsr ErrorExit	;unload driver if needed	brl Exit2	EXPORT Err4Err4		;       	jsr SetupFrame	;setup direct page stack frame	jsr ErrorExit	;unload driver if needed	brl Exit4	EXPORT Err6Err6	jsr SetupFrame	;setup direct page stack frame	jsr ErrorExit	;unload driver if needed	brl Exit6		EXPORT Err8Err8		;       	jsr SetupFrame	;setup direct page stack frame	jsr ErrorExit	;unload driver if needed	brl Exit8	EXPORT Err10Err10		;       	jsr SetupFrame	;setup direct page stack frame	jsr ErrorExit	;unload driver if needed	brl Exit10	EXPORT Err12Err12		;       	jsr SetupFrame	;setup direct page stack frame	jsr ErrorExit	;unload driver if needed	brl Exit12;This is a common little routine that all the error exits use to cause an unload of the;driver if there was an error trying to load and start it.  This is needed to cause each;call to attempt to load and start each time its called (not just the first call on that;channel.)ErrorExit	lda DriverError	;get error that caused this exit to happen	pha	;save error	cmp #BadChannel	;see if bad channel number is all	beq EOK	;dont unload then, just return error	lda #0	;we want unload and purge driver	jsr UnloadCurMediaDriver ;unload the current driverEOK	pla	;restore error no.	jsl DecBusyFlg	;dec. busy flag (because setup frame incs. it.	rts	ENDP	END